    def _apply_pending_subclass_choices(self, items: list[str]):
        """Apply pending subclass choices to current_character."""
        if not hasattr(self, 'current_character') or not self.current_character:
            QMessageBox.warning(self, "Uyarı", "Önce bir karakter oluşturun veya yükleyin.")
            return

        applied = []
        if 'subclasses_applied' not in self.current_character:
            self.current_character['subclasses_applied'] = []

        for it in items:
            if it not in self.current_character['subclasses_applied']:
                self.current_character['subclasses_applied'].append(it)
                applied.append(it)

        # Clear pending list
        self._pending_subclass_choices = []
        self.pending_widget.set_pending([])
        self.pending_widget.setVisible(False)

        # Save and refresh class features
        self._auto_save_character()
        if applied:
            QMessageBox.information(self, "Uygulandı", f"{len(applied)} arketip uygulandı: {', '.join(applied)}")
            # Refresh features/UI
            if hasattr(self, '_refresh_class_features'):
                self._refresh_class_features()

    def _clear_pending_subclass_choices(self):
        """Clear pending subclass choices without applying."""
