class PendingChoicesWidget(QWidget):
    def __init__(self, on_apply, on_clear, parent=None):
        super().__init__(parent)
        self.on_apply = on_apply
        self.on_clear = on_clear
        self.setStyleSheet("""
            background-color: #22313a;
            border: 1px solid #34495e;
            border-radius: 5px;
            margin: 5px 0;
        """)
        layout = QVBoxLayout()
        self.label = QLabel("Bekleyen Alt Sınıf Seçimleri")
        self.label.setStyleSheet("font-size: 14px; color: #f1c40f; font-weight: bold;")
        layout.addWidget(self.label)
        self.choices_label = QLabel("")
        self.choices_label.setStyleSheet("color: #ecf0f1; font-size: 13px;")
        layout.addWidget(self.choices_label)
        btn_layout = QHBoxLayout()
        self.apply_btn = QPushButton("Uygula")
        self.apply_btn.setStyleSheet("background-color: #27ae60; color: white;")
        self.apply_btn.clicked.connect(self._on_apply)
        btn_layout.addWidget(self.apply_btn)
        self.clear_btn = QPushButton("Temizle")
        self.clear_btn.setStyleSheet("background-color: #c0392b; color: white;")
        self.clear_btn.clicked.connect(self._on_clear)
        btn_layout.addWidget(self.clear_btn)
        layout.addLayout(btn_layout)
        self.setLayout(layout)

    def set_choices(self, choices: list[str]):
        self.choices_label.setText(", ".join(choices) if choices else "Yok")

    def _on_apply(self):
        if self.on_apply:
            self.on_apply()

    def _on_clear(self):
        if self.on_clear:
            self.on_clear()

