    def _on_asi_feat_choice_changed(self, choice):
        """ASI/Feat seçimi değiştiğinde UI'yi güncelle"""
        if choice == "ASI (Ability Score Increase)":
            self.asi_group.setVisible(True)
            self.feat_group.setVisible(False)
        else:  # Feat
            self.asi_group.setVisible(False)
            self.feat_group.setVisible(True)
            self._refresh_available_feats()

    def _refresh_available_feats(self):
        """Seçilebilir feat'leri güncelle"""
        try:
            # Mevcut karakter kontrolü
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                self.available_feats_list.clear()
                return
                
            filepath = self.current_character_file
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            # Karakterin mevcut feat'lerini al
            current_feats = character_data.get("feats", [])
            
            # Tüm feat'leri al
            all_feats = self.data.get("feats", {})
            
            self.available_feats_list.clear()
            
            for feat_name, feat_data in all_feats.items():
                # Prerequisite kontrolü
                prerequisites = feat_data.get("prerequisite", [])
                can_take = True
                
                for prereq in prerequisites:
                    if prereq not in current_feats:
                        can_take = False
                        break
                
                if can_take and feat_name not in current_feats:
                    feat_text = f"{feat_name}"
                    if feat_data.get("description"):
                        feat_text += f" - {feat_data['description'][:50]}..."
                    self.available_feats_list.addItem(feat_text)
                    
        except Exception as e:
            print(f"Feat listesi güncellenirken hata: {e}")

    def _filter_levelup_characters(self, search_text):
        """Seviye atlama karakter listesini filtrele"""
        try:
            if not search_text.strip():
                self._refresh_levelup_character_list()
                return
                
            search_text = search_text.lower().strip()
            filtered_count = 0
            
            for i in range(self.levelup_character_combo.count()):
                item_text = self.levelup_character_combo.itemText(i).lower()
                if search_text in item_text:
                    self.levelup_character_combo.setItemHidden(i, False)
                    filtered_count += 1
                else:
                    self.levelup_character_combo.setItemHidden(i, True)
            
            # Eğer hiç sonuç yoksa bilgi ver
            if filtered_count == 0:
                QMessageBox.information(self, "Arama Sonucu", "Arama kriterlerine uygun karakter bulunamadı.")
                
        except Exception as e:
            print(f"Karakter filtreleme hatası: {e}")

    def _refresh_levelup_character_list(self):
        """Seviye atlama karakter listesini yenile (GUI ve CLI kayıtları dahil)"""
        try:
            import json
            
            self.levelup_character_combo.clear()
            characters = []
            
            characters_dir = _ensure_characters_dir()
            if characters_dir.exists():
                for filepath in characters_dir.glob("*.json"):
                    try:
                        with open(filepath, 'r', encoding='utf-8') as f:
                            char_data = json.load(f)
                        # Sadece D&D 5e karakterleri
                        system = char_data.get("system")
                        if system not in ("DND5E", "Dnd5e", "dnd5e", None):
                            continue
                        char_name = char_data.get("name", "İsimsiz")
                        char_level = char_data.get("level", 1)
                        char_class = char_data.get("class", "")
                        display_name = f"{char_name} (Seviye {char_level} {char_class})"
                        self.levelup_character_combo.addItem(display_name, str(filepath))
                        characters.append((char_name, char_level, str(filepath)))
                    except Exception as e:
                        print(f"Karakter dosyası okunamadı {filepath}: {e}")
            
            if not characters:
                self.levelup_character_combo.addItem("Henüz karakter oluşturulmadı")
            
            # İlk karakteri seç ve yükle
            if characters:
                self.levelup_character_combo.setCurrentIndex(0)
                self._load_character_for_levelup()
                
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Karakter listesi yenilenemedi:\n{str(e)}")

    def _load_character_for_levelup(self):
        """Seçilen karakteri seviye atlama için yükle"""
        try:
            # Combo box'tan seçilen karakteri al
            current_index = self.levelup_character_combo.currentIndex()
            if current_index < 0:
                return
                
            filepath = self.levelup_character_combo.itemData(current_index)
            if not filepath:
                return
                
            # current_character_file'ı güncelle (diğer fonksiyonlar için)
            self.current_character_file = filepath
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
                
            # Karakter bilgisini göster
            char_name = character_data.get("name", "İsimsiz")
            char_level = character_data.get("level", 1)
            char_class = character_data.get("class", "")
            self.current_character_label.setText(f"{char_name} - Seviye {char_level} {char_class}")
                
            current_level = character_data.get("level", 1)
            self.current_level_label.setText(str(current_level))
            self.new_level_spin.setRange(current_level + 1, 20)
            self.new_level_spin.setValue(current_level + 1)
            
            # HP artışını hesapla
            self._on_level_change()
            
            # Yeni seçenekleri güncelle
            self._refresh_available_feats()
            self._update_character_preview()
            self._refresh_pending_choices()
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Karakter yüklenemedi:\n{str(e)}")

    def _update_character_preview(self):
        """Karakter önizlemesini güncelle"""
        try:
            # Mevcut karakter kontrolü
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                self.character_preview.clear()
                return
                
            filepath = self.current_character_file
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            # Önizleme metni oluştur
            preview_lines = []
            
            # Temel bilgiler
            preview_lines.append(f"🎭 {character_data.get('name', 'İsimsiz')}")
            preview_lines.append(f"Seviye {character_data.get('level', 1)} {character_data.get('class', 'Sınıfsız')}")
            preview_lines.append(f"Irk: {character_data.get('race', 'Irksız')}")
            preview_lines.append("")
            
            # Yetenek puanları
            preview_lines.append("📊 Yetenek Puanları:")
            raw_abilities = character_data.get("abilities", {})
            # CLI karakterlerinde abilities {'scores': {...}, 'modifiers': {...}} olabilir
            if isinstance(raw_abilities, dict) and "scores" in raw_abilities:
                abilities = raw_abilities.get("scores", {})
            else:
                abilities = raw_abilities
            for ability, score in abilities.items():
                try:
                    val = int(score)
                except (ValueError, TypeError):
                    continue
                modifier = (val - 10) // 2
                preview_lines.append(f"  {ability.title()}: {val} ({modifier:+d})")
            
            preview_lines.append("")
            
            # HP ve AC
            con_score =  abilities.get("constitution", 10)
            try:
                con_score = int(con_score)
            except (ValueError, TypeError):
                con_score = 10
            con_modifier = (con_score - 10) // 2
            class_hp = {
                "Barbarian": 12, "Fighter": 10, "Paladin": 10, "Ranger": 10,
                "Artificer": 8, "Bard": 8, "Cleric": 8, "Druid": 8, 
                "Monk": 8, "Rogue": 8, "Warlock": 8, "Sorcerer": 6, "Wizard": 6
            }
            char_class = character_data.get("class", "")
            hp_dice = class_hp.get(char_class, 6)
            max_hp = hp_dice + con_modifier + (hp_dice + con_modifier) * (character_data.get("level", 1) - 1)
            
            dex_modifier = (abilities.get("dexterity", 10) - 10) // 2
            base_ac = 10 + dex_modifier
            
            preview_lines.append(f"❤️ HP: {max_hp}")
            preview_lines.append(f"🛡️ AC: {base_ac}")
            preview_lines.append("")
            
            # Feat'ler
            feats = character_data.get("feats", [])
            if feats:
                preview_lines.append("🎯 Feat'ler:")
                for feat in feats:
                    preview_lines.append(f"  • {feat}")
                preview_lines.append("")
            
            # Büyüler
            spells = character_data.get("spells", {})
            if spells:
                preview_lines.append("🔮 Büyüler:")
                for spell_type, spell_list in spells.items():
                    if spell_list:
                        preview_lines.append(f"  {spell_type.title()}: {', '.join(spell_list)}")
                preview_lines.append("")
            
            preview_text = "\n".join(preview_lines)
            self.character_preview.setPlainText(preview_text)
            
        except Exception as e:
            print(f"Karakter önizleme güncellenirken hata: {e}")

    def _on_level_change(self):
        """Seviye değiştiğinde HP artışını hesapla"""
        try:
            # Mevcut karakter kontrolü
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                self.hp_gain_label.setText("0")
                return
                
            filepath = self.current_character_file
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
                
            current_level = character_data.get("level", 1)
            new_level = self.new_level_spin.value()
            
            if new_level <= current_level:
                self.hp_gain_label.setText("0")
                return
                
            # HP artışını hesapla
            char_class = character_data.get("class", "")
            constitution = character_data.get("abilities", {}).get("constitution", 10)
            con_modifier = (constitution - 10) // 2
            
            # Sınıf HP dice'ları
            hp_dice = {
                "Barbarian": 12, "Fighter": 10, "Paladin": 10, "Ranger": 10,
                "Artificer": 8, "Bard": 8, "Cleric": 8, "Druid": 8, 
                "Monk": 8, "Rogue": 8, "Warlock": 8,
                "Sorcerer": 6, "Wizard": 6
            }
            
            class_hp = hp_dice.get(char_class, 6)
            hp_gain = (new_level - current_level) * (class_hp + con_modifier)
            
            self.hp_gain_label.setText(str(hp_gain))
            
            # Yeni sınıf özelliklerini göster
            self._update_class_features(new_level)
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"HP hesaplanamadı:\n{str(e)}")

    def _update_class_features(self, new_level):
        """Yeni seviyede kazanılan sınıf özelliklerini güncelle"""
        try:
            self.new_features_list.clear()
            
            # Mevcut karakter kontrolü
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                return
                
            filepath = self.current_character_file
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
                
            char_class = character_data.get("class", "")
            current_level = character_data.get("level", 1)
            new_level = self.new_level_spin.value()
            
            if new_level <= current_level:
                return
                
            # Sınıf özelliklerini kontrol et - DÜZELTİLDİ
            classes = self.data.get("classes", {})
            if char_class in classes:
                class_data = classes[char_class]
                class_features = class_data.get("class_features", {})
                
                for level_str, level_data in class_features.items():
                    level_num = int(level_str)
                    if current_level < level_num <= new_level:
                        # Level data bir dict (features ve choices içeriyor)
                        if isinstance(level_data, dict):
                            features_list = level_data.get("features", [])
                            choices = level_data.get("choices", {})
                            
                            for feature in features_list:
                                self.new_features_list.addItem(f"Seviye {level_num}: {feature}")
                            
                            # Choices varsa göster
                            for choice_type, choice_options in choices.items():
                                if isinstance(choice_options, list):
                                    options_text = ", ".join(choice_options[:3])
                                    if len(choice_options) > 3:
                                        options_text += f" ... (+{len(choice_options) - 3} daha)"
                                    self.new_features_list.addItem(f"Seviye {level_num}: {choice_type} (Seçim: {options_text})")
                        elif isinstance(level_data, list):
                            # Eski format (sadece liste)
                            for feature in level_data:
                                self.new_features_list.addItem(f"Seviye {level_num}: {feature}")
                                
        except Exception as e:
            print(f"Sınıf özellikleri güncellenemedi: {e}")

    def _level_up_character(self):
        """Karakteri seviye atlat"""
        try:
            # Mevcut karakter kontrolü
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Lütfen önce bir karakter oluşturun veya yükleyin!")
                return
                
            filepath = self.current_character_file
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
                
            current_level = character_data.get("level", 1)
            new_level = self.new_level_spin.value()
            
            if new_level <= current_level:
                QMessageBox.warning(self, "Uyarı", "Yeni seviye mevcut seviyeden büyük olmalı!")
                return
                
            # HP artışını hesapla ve uygula
            char_class = character_data.get("class", "")
            constitution = character_data.get("abilities", {}).get("constitution", 10)
            con_modifier = (constitution - 10) // 2
            
            hp_dice = {
                "Barbarian": 12, "Fighter": 10, "Paladin": 10, "Ranger": 10,
                "Artificer": 8, "Bard": 8, "Cleric": 8, "Druid": 8, 
                "Monk": 8, "Rogue": 8, "Warlock": 8,
                "Sorcerer": 6, "Wizard": 6
            }
            
            class_hp = hp_dice.get(char_class, 6)
            
            # HP artışı hesaplama - DÜZELTİLDİ (her seviye için ayrı)
            if "hp" not in character_data:
                character_data["hp"] = class_hp + con_modifier  # Seviye 1 HP
            
            # Her seviye için HP artışı (ortalama: hit die/2 + 1 + CON modifier)
            average_roll = (class_hp // 2) + 1
            hp_gain = 0
            for level in range(current_level + 1, new_level + 1):
                hp_gain += average_roll + con_modifier
            
            # CLASS FEATURES - DÜZELTİLDİ (otomatik ekleme)
            if "features" not in character_data:
                character_data["features"] = []
            if "class_features" not in character_data:
                character_data["class_features"] = {}
            
            classes = self.data.get("classes", {})
            if char_class in classes:
                class_data = classes[char_class]
                class_features_dict = class_data.get("class_features", {})
                
                # Her seviye için class features'ları ekle
                gained_features = []
                for level in range(current_level + 1, new_level + 1):
                    level_str = str(level)
                    if level_str in class_features_dict:
                        level_features = class_features_dict[level_str]
                        
                        # Features listesi
                        if isinstance(level_features, dict):
                            features_list = level_features.get("features", [])
                            choices = level_features.get("choices", {})
                        elif isinstance(level_features, list):
                            features_list = level_features
                            choices = {}
                        else:
                            features_list = []
                            choices = {}
                        
                        # Features'ları karaktere ekle
                        for feature in features_list:
                            if feature not in character_data["features"]:
                                character_data["features"].append(feature)
                                gained_features.append((level, feature))
                        
                        # Class features dict'e ekle
                        if level_str not in character_data["class_features"]:
                            character_data["class_features"][level_str] = {
                                "features": features_list.copy(),
                                "choices": choices.copy() if choices else {}
                            }
                        
                        # Choices varsa (subclass seçimi gibi) pending_choices'a ekle
                        if choices:
                            for choice_type, choice_options in choices.items():
                                if "pending_choices" not in character_data:
                                    character_data["pending_choices"] = []
                                
                                # Bu choice daha önce eklenmiş mi kontrol et
                                already_pending = any(
                                    pc.get("type") == choice_type.lower().replace(" ", "_") and pc.get("level") == level
                                    for pc in character_data["pending_choices"]
                                )
                                
                                if not already_pending:
                                    character_data["pending_choices"].append({
                                        "type": choice_type.lower().replace(" ", "_"),
                                        "level": level,
                                        "description": f"Seviye {level} {choice_type} Seçimi",
                                        "options": choice_options if isinstance(choice_options, list) else []
                                    })
                        
                        # Expertise kontrolü - DÜZELTİLDİ (Bard 3. seviye, Rogue 1. seviye)
                        # Eğer "Expertise" feature'ı varsa, expertise seçimi ekle
                        expertise_in_features = any("expertise" in str(f).lower() for f in features_list)
                        
                        # Rogue için 1. seviye, Bard için 3. seviye
                        should_add_expertise = False
                        if char_class == "Rogue" and level == 1:
                            should_add_expertise = True  # Rogue always gets expertise at level 1
                        elif char_class == "Bard" and level == 3:
                            should_add_expertise = expertise_in_features  # Bard gets expertise if feature exists
                        
                        if should_add_expertise:
                            if "pending_choices" not in character_data:
                                character_data["pending_choices"] = []
                            
                            # Expertise seçimi daha önce eklenmiş mi kontrol et
                            already_pending = any(
                                pc.get("type", "").lower() == "expertise" and pc.get("level") == level
                                for pc in character_data["pending_choices"]
                            )
                            
                            if not already_pending:
                                character_data["pending_choices"].append({
                                    "type": "expertise",
                                    "level": level,
                                    "description": f"Seviye {level} Expertise Seçimi (2 skill)",
                                    "class": char_class,
                                    "count": 2  # 2 skill seçimi
                                })
                        
                        # Fighting Style kontrolü - DÜZELTİLDİ (Fighter 1, Paladin 2, Ranger 2)
                        if ("fighting style" in [str(f).lower() for f in features_list] or 
                            (char_class in ["Fighter", "Paladin", "Ranger"] and 
                             ((char_class == "Fighter" and level == 1) or 
                              (char_class in ["Paladin", "Ranger"] and level == 2)))):
                            if "pending_choices" not in character_data:
                                character_data["pending_choices"] = []
                            
                            # Fighting Style seçimi daha önce eklenmiş mi kontrol et
                            already_pending = any(
                                pc.get("type", "").lower() == "fighting_style" and pc.get("level") == level
                                for pc in character_data["pending_choices"]
                            )
                            
                            if not already_pending:
                                # Fighting Style seçeneklerini al (data'dan)
                                fighting_styles = self.data.get("fighting_styles", [])
                                if not fighting_styles:
                                    # Varsayılan Fighting Style'lar
                                    fighting_styles = [
                                        "Archery", "Defense", "Dueling", "Great Weapon Fighting",
                                        "Protection", "Two-Weapon Fighting", "Blind Fighting",
                                        "Interception", "Thrown Weapon Fighting", "Unarmed Fighting"
                                    ]
                                
                                character_data["pending_choices"].append({
                                    "type": "fighting_style",
                                    "level": level,
                                    "description": f"Seviye {level} Fighting Style Seçimi",
                                    "class": char_class,
                                    "options": fighting_styles,
                                    "count": 1
                                })
                        
                        # Metamagic kontrolü - DÜZELTİLDİ (Sorcerer 3, 10, 17)
                        if char_class == "Sorcerer" and ("metamagic" in [str(f).lower() for f in features_list] or level in [3, 10, 17]):
                            if "pending_choices" not in character_data:
                                character_data["pending_choices"] = []
                            
                            # Metamagic seçimi daha önce eklenmiş mi kontrol et
                            already_pending = any(
                                pc.get("type", "").lower() == "metamagic" and pc.get("level") == level
                                for pc in character_data["pending_choices"]
                            )
                            
                            if not already_pending:
                                # Metamagic seçeneklerini al (data'dan)
                                metamagic_options = self.data.get("metamagic_options", [])
                                if not metamagic_options:
                                    # Varsayılan Metamagic'ler
                                    metamagic_options = [
                                        "Careful Spell", "Distant Spell", "Empowered Spell",
                                        "Extended Spell", "Heightened Spell", "Quickened Spell",
                                        "Seeking Spell", "Subtle Spell", "Transmuted Spell",
                                        "Twinned Spell"
                                    ]
                                
                                # Kaç metamagic seçilebilir? (3. seviye: 2, 10. seviye: 1, 17. seviye: 1)
                                count = 2 if level == 3 else 1
                                
                                character_data["pending_choices"].append({
                                    "type": "metamagic",
                                    "level": level,
                                    "description": f"Seviye {level} Metamagic Seçimi ({count} metamagic)",
                                    "class": char_class,
                                    "options": metamagic_options,
                                    "count": count
                                })
                        
                        # Eldritch Invocations kontrolü - DÜZELTİLDİ (Warlock 2+)
                        if char_class == "Warlock" and level >= 2:
                            # Warlock her 2. seviyede invocation seçer (2, 5, 7, 9, 12, 15, 18)
                            invocation_levels = [2, 5, 7, 9, 12, 15, 18]
                            if level in invocation_levels:
                                if "pending_choices" not in character_data:
                                    character_data["pending_choices"] = []
                                
                                # Invocation seçimi daha önce eklenmiş mi kontrol et
                                already_pending = any(
                                    pc.get("type", "").lower() == "eldritch_invocations" and pc.get("level") == level
                                    for pc in character_data["pending_choices"]
                                )
                                
                                if not already_pending:
                                    # Eldritch Invocations seçeneklerini al (data'dan)
                                    invocations = self.data.get("eldritch_invocations", {})
                                    invocation_options = list(invocations.keys()) if isinstance(invocations, dict) else []
                                    if not invocation_options:
                                        # Varsayılan Invocations (bazıları)
                                        invocation_options = [
                                            "Agonizing Blast", "Armor of Shadows", "Beast Speech",
                                            "Beguiling Influence", "Book of Ancient Secrets",
                                            "Devil's Sight", "Eldritch Sight", "Eldritch Spear",
                                            "Eyes of the Rune Keeper", "Fiendish Vigor", "Gaze of Two Minds",
                                            "Lifedrinker", "Mask of Many Faces", "Master of Myriad Forms",
                                            "Misty Visions", "One with Shadows", "Otherworldly Leap",
                                            "Repelling Blast", "Thirsting Blade", "Whispers of the Grave"
                                        ]
                                    
                                    # Kaç invocation seçilebilir? (2. seviye: 2, sonraki: 1)
                                    count = 2 if level == 2 else 1
                                    
                                    character_data["pending_choices"].append({
                                        "type": "eldritch_invocations",
                                        "level": level,
                                        "description": f"Seviye {level} Eldritch Invocation Seçimi ({count} invocation)",
                                        "class": char_class,
                                        "options": invocation_options,
                                        "count": count
                                    })
                        
                        # Pact Boon kontrolü - DÜZELTİLDİ (Warlock 3)
                        if char_class == "Warlock" and level == 3:
                            if "pending_choices" not in character_data:
                                character_data["pending_choices"] = []
                            
                            # Pact Boon seçimi daha önce eklenmiş mi kontrol et
                            already_pending = any(
                                pc.get("type", "").lower() == "pact_boon" and pc.get("level") == level
                                for pc in character_data["pending_choices"]
                            )
                            
                            if not already_pending:
                                # Pact Boon seçeneklerini al (data'dan)
                                pact_boons = self.data.get("pact_boons", [])
                                if not pact_boons:
                                    # Varsayılan Pact Boons
                                    pact_boons = [
                                        "Pact of the Chain",
                                        "Pact of the Blade",
                                        "Pact of the Tome"
                                    ]
                                
                                character_data["pending_choices"].append({
                                    "type": "pact_boon",
                                    "level": level,
                                    "description": f"Seviye {level} Pact Boon Seçimi",
                                    "class": char_class,
                                    "options": pact_boons,
                                    "count": 1
                                })
            
            # ASI/Feat seçimi - DÜZELTİLDİ (4, 8, 12, 16, 19 - class'a göre)
            # Bazı class'lar (Fighter, Rogue) 6. seviyede de ASI alır ama genel olarak:
            asi_levels = [4, 8, 12, 16, 19]  # Genel ASI seviyeleri
            if char_class in ["Fighter", "Rogue"]:
                asi_levels = [4, 6, 8, 10, 12, 14, 16, 19]  # Fighter ve Rogue için özel
            
            # Eğer yeni seviye ASI seviyesiyse ve bu level'lardan birinde seçim yapıldıysa
            if new_level in asi_levels and hasattr(self, 'asi_feat_choice'):
                choice = self.asi_feat_choice.currentText()
                if choice == "ASI (Ability Score Increase)":
                    # ASI uygula
                    ability1 = self.asi_ability1.currentText().lower()
                    ability2 = self.asi_ability2.currentText().lower()
                    
                    if ability1 not in character_data["abilities"]:
                        character_data["abilities"][ability1] = 8
                    if ability2 not in character_data["abilities"]:
                        character_data["abilities"][ability2] = 8
                        
                    character_data["abilities"][ability1] += 1
                    character_data["abilities"][ability2] += 1
                elif choice == "Feat":
                    selected_feat = self.available_feats_list.currentItem()
                    if selected_feat:
                        feat_name = selected_feat.text().split(" (")[0].split(" - ")[0]
                        if "feats" not in character_data:
                            character_data["feats"] = []
                        if feat_name not in character_data["feats"]:
                            character_data["feats"].append(feat_name)
            
            # HP'yi güncelle
            character_data["hp"] += hp_gain
            
            # SPELL SLOTS güncelleme - DÜZELTİLDİ (otomatik hesaplama)
            character_data["level"] = new_level
            spell_slots = calculate_spell_slots(character_data, self.data)
            if spell_slots:
                character_data["spell_slots"] = spell_slots
            
            # SPELLS KNOWN güncelleme (Sorcerer, Bard, Warlock, Ranger için) - DÜZELTİLDİ
            spells_known_current = calculate_spells_known(character_data, self.data)
            spells_known_old = None
            if current_level > 1:
                # Eski seviye için spells known hesapla
                temp_char_old = character_data.copy()
                temp_char_old["level"] = current_level
                spells_known_old = calculate_spells_known(temp_char_old, self.data)
            
            if spells_known_current:
                character_data["spells_known"] = spells_known_current
                
                # Yeni seviyede kazanılan spell sayısını hesapla - DÜZELTİLDİ (Level Up Spell Selection)
                if spells_known_old:
                    current_total = spells_known_current.get("total", 0)
                    old_total = spells_known_old.get("total", 0)
                    new_spells_to_learn = current_total - old_total
                    
                    # Her seviye için ayrı hesapla (çoklu seviye atlama durumu)
                    for level in range(current_level + 1, new_level + 1):
                        temp_char_level = character_data.copy()
                        temp_char_level["level"] = level
                        spells_known_at_level = calculate_spells_known(temp_char_level, self.data)
                        temp_char_level["level"] = level - 1
                        spells_known_at_prev_level = calculate_spells_known(temp_char_level, self.data)
                        
                        if spells_known_at_level and spells_known_at_prev_level:
                            spells_at_level = spells_known_at_level.get("total", 0)
                            spells_at_prev_level = spells_known_at_prev_level.get("total", 0)
                            spells_to_learn_at_level = spells_at_level - spells_at_prev_level
                            
                            if spells_to_learn_at_level > 0:
                                # Pending choice ekle
                                if "pending_choices" not in character_data:
                                    character_data["pending_choices"] = []
                                
                                # Bu level için spell seçimi daha önce eklenmiş mi kontrol et
                                already_pending = any(
                                    pc.get("type") == "spell_selection" and pc.get("level") == level
                                    for pc in character_data["pending_choices"]
                                )
                                
                                if not already_pending:
                                    character_data["pending_choices"].append({
                                        "type": "spell_selection",
                                        "level": level,
                                        "description": f"Seviye {level} Spell Seçimi ({spells_to_learn_at_level} spell)",
                                        "class": char_class,
                                        "count": spells_to_learn_at_level,
                                        "spell_type": "known"  # Known caster
                                    })
                else:
                    # İlk seviye atlama (1 -> 2)
                    current_total = spells_known_current.get("total", 0)
                    # Seviye 1'deki spells known sayısını al
                    temp_char_lv1 = character_data.copy()
                    temp_char_lv1["level"] = 1
                    spells_known_lv1 = calculate_spells_known(temp_char_lv1, self.data)
                    
                    if spells_known_lv1:
                        lv1_total = spells_known_lv1.get("total", 0)
                        new_spells_to_learn = current_total - lv1_total
                        
                        if new_spells_to_learn > 0:
                            if "pending_choices" not in character_data:
                                character_data["pending_choices"] = []
                            
                            # Her seviye için spell seçimi ekle
                            for level in range(current_level + 1, new_level + 1):
                                temp_char_level = character_data.copy()
                                temp_char_level["level"] = level
                                spells_known_at_level = calculate_spells_known(temp_char_level, self.data)
                                temp_char_level["level"] = level - 1
                                spells_known_at_prev_level = calculate_spells_known(temp_char_level, self.data)
                                
                                if spells_known_at_level and spells_known_at_prev_level:
                                    spells_at_level = spells_known_at_level.get("total", 0)
                                    spells_at_prev_level = spells_known_at_prev_level.get("total", 0)
                                    spells_to_learn_at_level = spells_at_level - spells_at_prev_level
                                    
                                    if spells_to_learn_at_level > 0:
                                        already_pending = any(
                                            pc.get("type") == "spell_selection" and pc.get("level") == level
                                            for pc in character_data["pending_choices"]
                                        )
                                        
                                        if not already_pending:
                                            character_data["pending_choices"].append({
                                                "type": "spell_selection",
                                                "level": level,
                                                "description": f"Seviye {level} Spell Seçimi ({spells_to_learn_at_level} spell)",
                                                "class": char_class,
                                                "count": spells_to_learn_at_level,
                                                "spell_type": "known"
                                            })
            
            # Wizard için spellbook'a yeni spell ekleme - DÜZELTİLDİ (Level Up Spell Selection)
            if char_class == "Wizard":
                # Wizard her seviye 2 yeni spell öğrenir (spellbook'a eklenir)
                for level in range(current_level + 1, new_level + 1):
                    if "pending_choices" not in character_data:
                        character_data["pending_choices"] = []
                    
                    # Bu level için spell seçimi daha önce eklenmiş mi kontrol et
                    already_pending = any(
                        pc.get("type") == "wizard_spellbook" and pc.get("level") == level
                        for pc in character_data["pending_choices"]
                    )
                    
                    if not already_pending:
                        character_data["pending_choices"].append({
                            "type": "wizard_spellbook",
                            "level": level,
                            "description": f"Seviye {level} Spellbook'a 2 yeni spell ekle",
                            "class": "Wizard",
                            "count": 2,
                            "spell_type": "spellbook"  # Wizard spellbook
                        })
            
            # SPELLS PREPARED güncelleme (Wizard, Cleric, Druid, Paladin için)
            spells_prepared = calculate_spells_prepared(character_data, self.data)
            if spells_prepared is not None:
                character_data["spells_prepared"] = spells_prepared
            
            # Gained features mesajı hazırla
            features_msg = ""
            if gained_features:
                features_msg = "\n\nKazanılan Özellikler:\n"
                for level, feature in gained_features:
                    features_msg += f"  Seviye {level}: {feature}\n"
            
            # SPELL SLOTS güncelleme bilgisi (hesaplama özet ekranında yapılacak)
            # character_data içinde spell_slots hesaplanacak
            
            # Dosyaya kaydet
            with open(filepath, 'w', encoding='utf-8') as f:
                json.dump(character_data, f, ensure_ascii=False, indent=2)
            
            # Başarı mesajı
            success_msg = f"Karakter seviye {new_level}'e yükseltildi!\nHP artışı: +{hp_gain}"
            if features_msg:
                success_msg += features_msg
            
            # Pending choices varsa bilgi ver
            if character_data.get("pending_choices"):
                pending_count = len(character_data["pending_choices"])
                success_msg += f"\n\n⚠️ {pending_count} bekleyen seçim var (Subclass, Feat, vb.)"
            
            QMessageBox.information(self, "Başarılı", success_msg)
            
            # Mevcut karakter bilgisini yenile
            self._refresh_current_character_info()
            
            # Level up sekmesindeki bilgileri de güncelle
            if hasattr(self, '_update_class_features'):
                self._update_class_features(new_level)
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Seviye atlama başarısız:\n{str(e)}")

    def _refresh_pending_choices(self):
        """Bekleyen seçimleri güncelle"""
        try:
            # Mevcut karakter kontrolü
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                self.pending_choices_list.clear()
                return
                
            filepath = self.current_character_file
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            # Bekleyen seçimleri temizle
            self.pending_choices_list.clear()
            
            # Bekleyen seçimleri listele
            pending_choices = character_data.get("pending_choices", [])
            for choice in pending_choices:
                choice_text = f"Seviye {choice['level']}: {choice['description']}"
                item = QListWidgetItem(choice_text)
                item.setData(Qt.UserRole, choice)  # Seçim verisini sakla
                self.pending_choices_list.addItem(item)
                
        except Exception as e:
            print(f"Bekleyen seçimler güncellenirken hata: {e}")

    def _complete_pending_choice(self):
        """Seçili bekleyen seçimi tamamla"""
        try:
            selected_item = self.pending_choices_list.currentItem()
            if not selected_item:
                QMessageBox.warning(self, "Uyarı", "Lütfen tamamlamak istediğiniz seçimi seçin!")
                return
            
            choice_data = selected_item.data(Qt.UserRole)
            choice_type = choice_data.get("type", "").lower()
            
            # Feat seçimi
            if choice_type == "feat":
                self._complete_pending_feat_choice(choice_data)
            # Expertise seçimi (Rogue 1. seviye, Bard 3. seviye)
            elif choice_type == "expertise":
                self._complete_pending_expertise_choice(choice_data)
            # Spell seçimi (Level Up Sonrası) - DÜZELTİLDİ (Level Up Spell Selection)
            elif choice_type == "spell_selection" or choice_type == "wizard_spellbook":
                self._complete_pending_spell_choice(choice_data)
            # Fighting Style seçimi - DÜZELTİLDİ (Fighter 1, Paladin 2, Ranger 2)
            elif choice_type == "fighting_style":
                self._complete_pending_choice_with_options(choice_data, "Fighting Style")
            # Metamagic seçimi - DÜZELTİLDİ (Sorcerer 3, 10, 17)
            elif choice_type == "metamagic":
                self._complete_pending_choice_with_options(choice_data, "Metamagic", multi_select=True)
            # Eldritch Invocations seçimi - DÜZELTİLDİ (Warlock 2+)
            elif choice_type == "eldritch_invocations":
                self._complete_pending_choice_with_options(choice_data, "Eldritch Invocation", multi_select=True)
            # Pact Boon seçimi - DÜZELTİLDİ (Warlock 3)
            elif choice_type == "pact_boon":
                self._complete_pending_choice_with_options(choice_data, "Pact Boon")
            # Subclass/Archetype seçimleri (bard_college, vb.)
            elif "college" in choice_type or "archetype" in choice_type or "domain" in choice_type or "origin" in choice_type or "patron" in choice_type or "school" in choice_type or "tradition" in choice_type or "circle" in choice_type or "oath" in choice_type or "conclave" in choice_type or "way" in choice_type or choice_type.endswith("_choice"):
                # Genel choice seçimi (subclass olabilir)
                if "options" in choice_data and isinstance(choice_data["options"], list) and len(choice_data["options"]) > 0:
                    self._complete_pending_subclass_choice(choice_data)
                else:
                    QMessageBox.information(self, "Bilgi", f"Bu seçim türü henüz desteklenmiyor: {choice_type}")
            else:
                # Genel choice seçimi (subclass olabilir)
                if "options" in choice_data and isinstance(choice_data["options"], list) and len(choice_data["options"]) > 0:
                    self._complete_pending_subclass_choice(choice_data)
                else:
                    QMessageBox.information(self, "Bilgi", f"Bu seçim türü henüz desteklenmiyor: {choice_type}")
                
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Bekleyen seçim tamamlanırken hata oluştu:\n{str(e)}")

    def _complete_pending_feat_choice(self, choice_data):
        """Bekleyen feat seçimini tamamla"""
        try:
            # Feat seçim dialog'u aç
            feat_dialog = QDialog(self)
            feat_dialog.setWindowTitle(f"Feat Seçimi - {choice_data['description']}")
            feat_dialog.setModal(True)
            feat_dialog.resize(500, 400)
            
            layout = QVBoxLayout(feat_dialog)
            
            # Başlık
            title_label = QLabel(f"Seviye {choice_data['level']} için feat seçin:")
            title_label.setStyleSheet("font-weight: bold; font-size: 14px;")
            layout.addWidget(title_label)
            
            # Mevcut karakter bilgilerini al
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Mevcut karakter bulunamadı!")
                return
                
            filepath = self.current_character_file
            
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            # Seçilebilir feat'leri al
            current_feats = character_data.get("feats", [])
            all_feats = self.data.get("feats", {})
            
            feat_list = QListWidget()
            for feat_name, feat_data in all_feats.items():
                # Prerequisite kontrolü
                prerequisites = feat_data.get("prerequisite", [])
                can_take = True
                
                for prereq in prerequisites:
                    if prereq not in current_feats:
                        can_take = False
                        break
                
                if can_take and feat_name not in current_feats:
                    feat_text = f"{feat_name}"
                    if feat_data.get("description"):
                        feat_text += f" - {feat_data['description'][:100]}..."
                    feat_list.addItem(feat_text)
            
            layout.addWidget(feat_list)
            
            # Butonlar
            button_layout = QHBoxLayout()
            
            cancel_btn = QPushButton("İptal")
            cancel_btn.clicked.connect(feat_dialog.reject)
            button_layout.addWidget(cancel_btn)
            
            select_btn = QPushButton("Seç")
            select_btn.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    padding: 8px 16px;
                    font-weight: bold;
                    border-radius: 4px;
                }
                QPushButton:hover {
                    background-color: #229954;
                }
            """)
            
            def on_feat_selected():
                selected_feat = feat_list.currentItem()
                if not selected_feat:
                    QMessageBox.warning(feat_dialog, "Uyarı", "Lütfen bir feat seçin!")
                    return
                
                feat_name = selected_feat.text().split(" - ")[0]
                
                # Feat'i karaktere ekle
                if "feats" not in character_data:
                    character_data["feats"] = []
                character_data["feats"].append(feat_name)
                
                # Bekleyen seçimi kaldır
                pending_choices = character_data.get("pending_choices", [])
                pending_choices = [c for c in pending_choices if c != choice_data]
                character_data["pending_choices"] = pending_choices
                
                # Dosyaya kaydet
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(character_data, f, ensure_ascii=False, indent=2)
                
                QMessageBox.information(feat_dialog, "Başarılı", f"{feat_name} feat'i eklendi!")
                feat_dialog.accept()
                
                # Listeleri yenile
                self._refresh_current_character_info()
                self._refresh_pending_choices()
                self._update_character_preview()
            
            select_btn.clicked.connect(on_feat_selected)
            button_layout.addWidget(select_btn)
            
            layout.addLayout(button_layout)
            feat_dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Feat seçimi tamamlanırken hata oluştu:\n{str(e)}")

    def _complete_pending_choice_with_options(self, choice_data, choice_title, multi_select=False):
        """Bekleyen seçimi tamamla (options listesi ile - Fighting Style, Metamagic, Invocations, vb.)"""
        try:
            # Seçim dialog'u aç
            choice_dialog = QDialog(self)
            choice_dialog.setWindowTitle(f"{choice_title} Seçimi - {choice_data.get('description', '')}")
            choice_dialog.setModal(True)
            choice_dialog.resize(500, 450)
            
            layout = QVBoxLayout(choice_dialog)
            
            # Başlık
            title_label = QLabel(f"{choice_data.get('description', f'{choice_title} Seçimi')}:")
            title_label.setStyleSheet("font-weight: bold; font-size: 14px;")
            layout.addWidget(title_label)
            
            count = choice_data.get("count", 1)
            if multi_select:
                info_label = QLabel(f"Lütfen {count} seçenek seçin:")
            else:
                info_label = QLabel(f"Lütfen 1 seçenek seçin:")
            info_label.setStyleSheet("color: #666; font-size: 12px;")
            layout.addWidget(info_label)
            
            # Mevcut karakter bilgilerini al
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Mevcut karakter bulunamadı!")
                return
                
            filepath = self.current_character_file
            
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            # Seçilebilir seçenekleri al
            options = choice_data.get("options", [])
            if not options:
                QMessageBox.warning(choice_dialog, "Uyarı", "Seçenekler bulunamadı!")
                return
            
            # Mevcut seçimleri al (duplicate kontrolü için)
            choice_type = choice_data.get("type", "").lower()
            existing_choices = []
            
            # Karakter verisinden mevcut seçimleri al
            if choice_type == "fighting_style":
                existing_choices = character_data.get("fighting_styles", [])
            elif choice_type == "metamagic":
                existing_choices = character_data.get("metamagics", [])
            elif choice_type == "eldritch_invocations":
                existing_choices = character_data.get("eldritch_invocations", [])
            elif choice_type == "pact_boon":
                existing_choices = [character_data.get("pact_boon", "")]
            
            # List widget
            options_list = QListWidget()
            if multi_select:
                options_list.setSelectionMode(QAbstractItemView.MultiSelection)
            else:
                options_list.setSelectionMode(QAbstractItemView.SingleSelection)
            
            for option in options:
                # Eğer zaten seçilmişse göster ama seçilemez yap
                is_already_selected = option in existing_choices if isinstance(existing_choices, list) else option == existing_choices
                item_text = f"{'✓ ' if is_already_selected else ''}{option}"
                item = QListWidgetItem(item_text)
                if is_already_selected:
                    item.setForeground(QColor("#95a5a6"))  # Gri - zaten seçilmiş
                    item.setFlags(item.flags() & ~Qt.ItemIsEnabled)  # Seçilemez yap
                options_list.addItem(item)
            
            layout.addWidget(options_list)
            
            # Seçilen sayısı gösterimi (multi-select için)
            if multi_select:
                selected_count_label = QLabel(f"Seçilen: 0 / {count}")
                selected_count_label.setStyleSheet("color: #27ae60; font-weight: bold;")
                layout.addWidget(selected_count_label)
                
                def update_selected_count():
                    selected = len(options_list.selectedItems())
                    selected_count_label.setText(f"Seçilen: {selected} / {count}")
                    if selected == count:
                        selected_count_label.setStyleSheet("color: #27ae60; font-weight: bold;")
                    elif selected > count:
                        selected_count_label.setStyleSheet("color: #e74c3c; font-weight: bold;")
                    else:
                        selected_count_label.setStyleSheet("color: #f39c12; font-weight: bold;")
                
                options_list.itemSelectionChanged.connect(update_selected_count)
            
            # Butonlar
            button_layout = QHBoxLayout()
            
            cancel_btn = QPushButton("İptal")
            cancel_btn.clicked.connect(choice_dialog.reject)
            button_layout.addWidget(cancel_btn)
            
            select_btn = QPushButton("Seç")
            select_btn.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    padding: 8px 16px;
                    font-weight: bold;
                    border-radius: 4px;
                }
                QPushButton:hover {
                    background-color: #229954;
                }
            """)
            
            def on_option_selected():
                if multi_select:
                    selected_items = options_list.selectedItems()
                    if len(selected_items) != count:
                        QMessageBox.warning(choice_dialog, "Uyarı", f"Lütfen tam olarak {count} seçenek seçin!")
                        return
                    
                    selected_options = []
                    for item in selected_items:
                        option_name = item.text().replace("✓ ", "").strip()
                        selected_options.append(option_name)
                else:
                    selected_item = options_list.currentItem()
                    if not selected_item:
                        QMessageBox.warning(choice_dialog, "Uyarı", "Lütfen bir seçenek seçin!")
                        return
                    
                    option_name = selected_item.text().replace("✓ ", "").strip()
                    selected_options = [option_name]
                
                # Seçimleri karaktere ekle
                if choice_type == "fighting_style":
                    if "fighting_styles" not in character_data:
                        character_data["fighting_styles"] = []
                    for option in selected_options:
                        if option not in character_data["fighting_styles"]:
                            character_data["fighting_styles"].append(option)
                elif choice_type == "metamagic":
                    if "metamagics" not in character_data:
                        character_data["metamagics"] = []
                    for option in selected_options:
                        if option not in character_data["metamagics"]:
                            character_data["metamagics"].append(option)
                elif choice_type == "eldritch_invocations":
                    if "eldritch_invocations" not in character_data:
                        character_data["eldritch_invocations"] = []
                    for option in selected_options:
                        if option not in character_data["eldritch_invocations"]:
                            character_data["eldritch_invocations"].append(option)
                elif choice_type == "pact_boon":
                    character_data["pact_boon"] = selected_options[0] if selected_options else ""
                
                # Bekleyen seçimi kaldır
                pending_choices = character_data.get("pending_choices", [])
                filtered_choices = []
                for c in pending_choices:
                    c_type = str(c.get("type", "")).lower()
                    c_level = c.get("level")
                    choice_level = choice_data.get("level")
                    if not (c_type == choice_type and c_level == choice_level):
                        filtered_choices.append(c)
                character_data["pending_choices"] = filtered_choices
                
                # Dosyaya kaydet
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(character_data, f, ensure_ascii=False, indent=2)
                
                QMessageBox.information(choice_dialog, "Başarılı", f"{len(selected_options)} {choice_title.lower()} seçildi!")
                choice_dialog.accept()
                
                # Listeleri yenile
                self._refresh_current_character_info()
                self._refresh_pending_choices()
                if hasattr(self, '_update_character_preview'):
                    self._update_character_preview()
            
            select_btn.clicked.connect(on_option_selected)
            button_layout.addWidget(select_btn)
            
            layout.addLayout(button_layout)
            choice_dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"{choice_title} seçimi tamamlanırken hata oluştu:\n{str(e)}")
            import traceback
            print(f"{choice_title} seçim hatası: {traceback.format_exc()}")

    def _complete_pending_subclass_choice(self, choice_data):
        """Bekleyen subclass/archetype seçimini tamamla"""
        try:
            # Subclass seçim dialog'u aç
            subclass_dialog = QDialog(self)
            choice_type_display = choice_data.get("description", "Subclass Seçimi").split(": ")[-1] if ":" in choice_data.get("description", "") else choice_data.get("type", "Subclass").replace("_", " ").title()
            subclass_dialog.setWindowTitle(f"Subclass Seçimi - {choice_type_display}")
            subclass_dialog.setModal(True)
            subclass_dialog.resize(600, 500)
            
            layout = QVBoxLayout(subclass_dialog)
            
            # Başlık
            title_label = QLabel(f"{choice_data.get('description', 'Subclass Seçimi')}")
            title_label.setStyleSheet("font-weight: bold; font-size: 14px;")
            layout.addWidget(title_label)
            
            info_label = QLabel("Lütfen bir subclass seçin:")
            info_label.setStyleSheet("color: #666; font-size: 12px;")
            layout.addWidget(info_label)
            
            # Mevcut karakter bilgilerini al
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Mevcut karakter bulunamadı!")
                return
                
            filepath = self.current_character_file
            
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            char_class = character_data.get("class", "")
            
            # Seçenekleri al
            options = choice_data.get("options", [])
            
            if not options:
                QMessageBox.warning(self, "Uyarı", "Bu seçim için seçenek bulunamadı!")
                return
            
            # Subclass listesi
            subclass_list = QListWidget()
            subclass_list.setStyleSheet("""
                QListWidget::item {
                    padding: 8px;
                    border-bottom: 1px solid #ddd;
                }
                QListWidget::item:hover {
                    background-color: #e8f4f8;
                }
                QListWidget::item:selected {
                    background-color: #3498db;
                    color: white;
                }
            """)
            
            # Class data'dan subclass bilgilerini çek
            classes = self.data.get("classes", {})
            class_data = classes.get(char_class, {})
            subclass_features = class_data.get("subclasses", {}) or class_data.get("archetypes", {})
            
            for subclass_name in options:
                item_text = subclass_name
                
                # Subclass açıklaması varsa göster
                if subclass_name in subclass_features:
                    subclass_info = subclass_features[subclass_name]
                    if isinstance(subclass_info, dict):
                        description = subclass_info.get("description", "")
                        if description:
                            item_text += f"\n  {description[:150]}..." if len(description) > 150 else f"\n  {description}"
                
                subclass_list.addItem(item_text)
            
            layout.addWidget(subclass_list)
            
            # Butonlar
            button_layout = QHBoxLayout()
            
            cancel_btn = QPushButton("İptal")
            cancel_btn.clicked.connect(subclass_dialog.reject)
            button_layout.addWidget(cancel_btn)
            
            select_btn = QPushButton("Seç")
            select_btn.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    padding: 8px 16px;
                    font-weight: bold;
                    border-radius: 4px;
                }
                QPushButton:hover {
                    background-color: #229954;
                }
            """)
            
            def on_subclass_selected():
                selected_item = subclass_list.currentItem()
                if not selected_item:
                    QMessageBox.warning(subclass_dialog, "Uyarı", "Lütfen bir subclass seçin!")
                    return
                
                subclass_name = selected_item.text().split("\n")[0].strip()
                
                # Subclass'ı karaktere ekle
                character_data["subclass"] = subclass_name
                character_data["archetype"] = subclass_name  # Eski format uyumluluğu için
                
                # Subclass features'ları ekle
                if subclass_name in subclass_features:
                    subclass_info = subclass_features[subclass_name]
                    if isinstance(subclass_info, dict):
                        subclass_feature_list = subclass_info.get("features", [])
                        if subclass_feature_list:
                            if "features" not in character_data:
                                character_data["features"] = []
                            # Subclass features'ları ekle (duplicate kontrolü ile)
                            for feature in subclass_feature_list:
                                if feature not in character_data["features"]:
                                    character_data["features"].append(feature)
                
                # Choice type'ına göre özel alan ekle (örn: Bard College için "college")
                choice_type = choice_data.get("type", "").lower()
                if "college" in choice_type:
                    character_data["college"] = subclass_name
                elif "domain" in choice_type:
                    character_data["domain"] = subclass_name
                elif "patron" in choice_type:
                    character_data["patron"] = subclass_name
                elif "school" in choice_type:
                    character_data["school"] = subclass_name
                elif "tradition" in choice_type:
                    character_data["tradition"] = subclass_name
                elif "oath" in choice_type:
                    character_data["oath"] = subclass_name
                elif "circle" in choice_type:
                    character_data["circle"] = subclass_name
                elif "conclave" in choice_type:
                    character_data["conclave"] = subclass_name
                elif "way" in choice_type:
                    character_data["way"] = subclass_name
                
                # Bekleyen seçimi kaldır - DÜZELTİLDİ (daha güvenli karşılaştırma)
                pending_choices = character_data.get("pending_choices", [])
                # Orijinal choice_data'yı bul ve kaldır
                choice_type = choice_data.get("type", "").lower()
                choice_level = choice_data.get("level")
                
                filtered_choices = []
                for c in pending_choices:
                    # Eşleşme kontrolü - type ve level eşleşiyorsa kaldır
                    c_type = str(c.get("type", "")).lower()
                    c_level = c.get("level")
                    
                    if not (c_type == choice_type and c_level == choice_level):
                        filtered_choices.append(c)
                
                character_data["pending_choices"] = filtered_choices
                
                # Dosyaya kaydet
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(character_data, f, ensure_ascii=False, indent=2)
                
                QMessageBox.information(subclass_dialog, "Başarılı", f"{subclass_name} seçildi ve karaktere eklendi!")
                subclass_dialog.accept()
                
                # Listeleri yenile
                self._refresh_current_character_info()
                self._refresh_pending_choices()
                if hasattr(self, '_update_character_preview'):
                    self._update_character_preview()
                if hasattr(self, '_refresh_class_features'):
                    self._refresh_class_features()
            
            select_btn.clicked.connect(on_subclass_selected)
            button_layout.addWidget(select_btn)
            
            layout.addLayout(button_layout)
            subclass_dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Subclass seçimi tamamlanırken hata oluştu:\n{str(e)}")
            import traceback
            print(f"Subclass seçim hatası: {traceback.format_exc()}")

    def _complete_pending_spell_choice(self, choice_data):
        """Bekleyen spell seçimini tamamla (Known casters ve Wizard spellbook)"""
        try:
            # Mevcut karakter bilgilerini al
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Mevcut karakter bulunamadı!")
                return
                
            filepath = self.current_character_file
            
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            char_class = character_data.get("class", "")
            level = character_data.get("level", 1)
            spell_type = choice_data.get("spell_type", "known")  # "known" veya "spellbook"
            count = choice_data.get("count", 1)
            choice_level = choice_data.get("level", level)
            
            # Spell seçim dialog'u aç
            spell_dialog = QDialog(self)
            spell_dialog.setWindowTitle(f"Spell Seçimi - {choice_data.get('description', 'Büyü Seçimi')}")
            spell_dialog.setModal(True)
            spell_dialog.resize(600, 500)
            
            layout = QVBoxLayout(spell_dialog)
            
            # Başlık
            title_text = f"{choice_data.get('description', 'Spell Seçimi')}"
            if spell_type == "spellbook":
                title_text += " (Spellbook'a eklenecek)"
            else:
                title_text += " (Bilinen spell'ler)"
            
            title_label = QLabel(title_text)
            title_label.setStyleSheet("font-weight: bold; font-size: 14px;")
            layout.addWidget(title_label)
            
            info_label = QLabel(f"Lütfen {count} spell seçin:")
            info_label.setStyleSheet("color: #666; font-size: 12px;")
            layout.addWidget(info_label)
            
            # Seviye seçimi (spell level)
            level_layout = QHBoxLayout()
            level_layout.addWidget(QLabel("Büyü Seviyesi:"))
            spell_level_combo = QComboBox()
            spell_level_combo.addItems(["Cantrip", "1. Seviye", "2. Seviye", "3. Seviye", "4. Seviye", "5. Seviye", "6. Seviye", "7. Seviye", "8. Seviye", "9. Seviye"])
            level_layout.addWidget(spell_level_combo)
            level_layout.addStretch()
            layout.addLayout(level_layout)
            
            # Seçilebilir spell'ler listesi
            spell_list = QListWidget()
            spell_list.setSelectionMode(QAbstractItemView.MultiSelection)
            
            def update_spell_list():
                spell_list.clear()
                selected_level = spell_level_combo.currentText()
                
                # Level numarasını çıkar
                if selected_level == "Cantrip":
                    spell_level_num = 0
                    level_key = "cantrips"
                else:
                    spell_level_num = int(selected_level.split(".")[0])
                    level_key = f"level_{spell_level_num}"
                
                # Karakterin class'ına göre spell'leri al
                class_spells = self.data.get("classes", {}).get(char_class, {}).get("spells", {})
                available_spells = class_spells.get(level_key, [])
                
                # Eğer karakter seviyesinden daha yüksek seviye spell varsa filtrele
                filtered_spells = []
                for spell_name in available_spells:
                    spell_data = self.data.get("spells", {}).get(spell_name, {})
                    spell_spell_level = spell_data.get("level", 0)
                    if spell_spell_level <= level:
                        filtered_spells.append(spell_name)
                
                # Mevcut spell'leri kontrol et (tekrar seçilmesin)
                existing_spells = []
                if spell_type == "spellbook":
                    spellbook = character_data.get("spellbook", {})
                    for spell_list_key, spells in spellbook.items():
                        existing_spells.extend(spells)
                else:
                    spells = character_data.get("spells", {})
                    for spell_list_key, spells_list in spells.items():
                        existing_spells.extend(spells_list)
                
                # Spell'leri listele
                for spell_name in filtered_spells:
                    if spell_name not in existing_spells:
                        spell_data = self.data.get("spells", {}).get(spell_name, {})
                        school = spell_data.get("school", "Unknown")
                        spell_text = f"{spell_name} ({school})"
                        spell_list.addItem(spell_text)
            
            spell_level_combo.currentTextChanged.connect(update_spell_list)
            update_spell_list()  # İlk yükleme
            
            layout.addWidget(QLabel("Seçilebilir Büyüler:"))
            layout.addWidget(spell_list)
            
            # Seçilen spell sayısı gösterimi
            selected_count_label = QLabel("Seçilen: 0 / " + str(count))
            selected_count_label.setStyleSheet("color: #27ae60; font-weight: bold;")
            layout.addWidget(selected_count_label)
            
            def update_selected_count():
                selected = len(spell_list.selectedItems())
                selected_count_label.setText(f"Seçilen: {selected} / {count}")
                if selected == count:
                    selected_count_label.setStyleSheet("color: #27ae60; font-weight: bold;")
                elif selected > count:
                    selected_count_label.setStyleSheet("color: #e74c3c; font-weight: bold;")
                else:
                    selected_count_label.setStyleSheet("color: #f39c12; font-weight: bold;")
            
            spell_list.itemSelectionChanged.connect(update_selected_count)
            
            # Butonlar
            button_layout = QHBoxLayout()
            
            cancel_btn = QPushButton("İptal")
            cancel_btn.clicked.connect(spell_dialog.reject)
            button_layout.addWidget(cancel_btn)
            
            select_btn = QPushButton("Seç")
            select_btn.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    padding: 8px 16px;
                    font-weight: bold;
                    border-radius: 4px;
                }
                QPushButton:hover {
                    background-color: #229954;
                }
            """)
            
            def on_spell_selected():
                selected_items = spell_list.selectedItems()
                if len(selected_items) != count:
                    QMessageBox.warning(spell_dialog, "Uyarı", f"Lütfen tam olarak {count} spell seçin!")
                    return
                
                selected_spells = []
                for item in selected_items:
                    spell_name = item.text().split(" (")[0]
                    selected_spells.append(spell_name)
                
                # Spell'leri karaktere ekle
                if spell_type == "spellbook":
                    # Wizard spellbook'a ekle
                    if "spellbook" not in character_data:
                        character_data["spellbook"] = {}
                    
                    # Spell level'ına göre ekle
                    for spell_name in selected_spells:
                        spell_data = self.data.get("spells", {}).get(spell_name, {})
                        spell_level = spell_data.get("level", 0)
                        
                        if spell_level == 0:
                            level_key = "cantrips"
                        else:
                            level_key = f"level_{spell_level}"
                        
                        if level_key not in character_data["spellbook"]:
                            character_data["spellbook"][level_key] = []
                        
                        if spell_name not in character_data["spellbook"][level_key]:
                            character_data["spellbook"][level_key].append(spell_name)
                else:
                    # Known spells'e ekle
                    if "spells" not in character_data:
                        character_data["spells"] = {}
                    
                    for spell_name in selected_spells:
                        spell_data = self.data.get("spells", {}).get(spell_name, {})
                        spell_level = spell_data.get("level", 0)
                        
                        if spell_level == 0:
                            level_key = "cantrips"
                        else:
                            level_key = f"level_{spell_level}"
                        
                        if level_key not in character_data["spells"]:
                            character_data["spells"][level_key] = []
                        
                        if spell_name not in character_data["spells"][level_key]:
                            character_data["spells"][level_key].append(spell_name)
                
                # Bekleyen seçimi kaldır
                pending_choices = character_data.get("pending_choices", [])
                filtered_choices = []
                for c in pending_choices:
                    c_type = str(c.get("type", "")).lower()
                    c_level = c.get("level")
                    if not (c_type == choice_data.get("type", "").lower() and c_level == choice_level):
                        filtered_choices.append(c)
                character_data["pending_choices"] = filtered_choices
                
                # Dosyaya kaydet
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(character_data, f, ensure_ascii=False, indent=2)
                
                QMessageBox.information(spell_dialog, "Başarılı", f"{len(selected_spells)} spell eklendi!")
                spell_dialog.accept()
                
                # Listeleri yenile
                self._refresh_current_character_info()
                self._refresh_pending_choices()
                if hasattr(self, '_update_character_preview'):
                    self._update_character_preview()
                if hasattr(self, '_update_spells_list'):
                    self._update_spells_list()
                if hasattr(self, '_refresh_spellbook_display'):
                    self._refresh_spellbook_display()
            
            select_btn.clicked.connect(on_spell_selected)
            button_layout.addWidget(select_btn)
            
            layout.addLayout(button_layout)
            spell_dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Spell seçimi tamamlanırken hata oluştu:\n{str(e)}")
            import traceback
            print(f"Spell seçim hatası: {traceback.format_exc()}")

    def _complete_pending_expertise_choice(self, choice_data):
        """Bekleyen expertise seçimini tamamla"""
        try:
            # Expertise seçim dialog'u aç
            expertise_dialog = QDialog(self)
            expertise_dialog.setWindowTitle(f"Expertise Seçimi - {choice_data.get('description', 'Skill Seçimi')}")
            expertise_dialog.setModal(True)
            expertise_dialog.resize(500, 450)
            
            layout = QVBoxLayout(expertise_dialog)
            
            # Başlık
            title_label = QLabel(f"{choice_data.get('description', 'Expertise Seçimi')}")
            title_label.setStyleSheet("font-weight: bold; font-size: 14px;")
            layout.addWidget(title_label)
            
            count = choice_data.get("count", 2)
            info_label = QLabel(f"Lütfen {count} skill seçin (Expertise = Double Proficiency Bonus):")
            info_label.setStyleSheet("color: #666; font-size: 12px;")
            layout.addWidget(info_label)
            
            # Mevcut karakter bilgilerini al
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Mevcut karakter bulunamadı!")
                return
                
            filepath = self.current_character_file
            
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            # Proficient skill'leri al (sadece proficient skill'lere expertise verilebilir)
            proficient_skills = character_data.get("skills", {}).get("proficiencies", [])
            current_expertise = character_data.get("skills", {}).get("expertise", [])
            
            if not proficient_skills:
                QMessageBox.warning(self, "Uyarı", "Önce proficient skill'ler seçmelisiniz!")
                return
            
            # Skill listesi (proficient skill'ler)
            skill_list = QListWidget()
            skill_list.setSelectionMode(QtWidgets.QAbstractItemView.MultiSelection)
            skill_list.setStyleSheet("""
                QListWidget::item {
                    padding: 8px;
                    border-bottom: 1px solid #ddd;
                }
                QListWidget::item:hover {
                    background-color: #e8f4f8;
                }
                QListWidget::item:selected {
                    background-color: #3498db;
                    color: white;
                }
            """)
            
            # Tüm skill'leri göster (proficient olanları işaretle)
            all_skills = self.data.get("skills", {})
            for skill_name in sorted(all_skills.keys()):
                item_text = skill_name
                if skill_name in proficient_skills:
                    item_text += " ✓ (Proficient)"
                if skill_name in current_expertise:
                    item_text += " ⭐ (Already has Expertise)"
                skill_list.addItem(item_text)
            
            layout.addWidget(skill_list)
            
            # Seçim sayısı kontrolü
            selection_info = QLabel(f"Seçim: 0 / {count}")
            selection_info.setStyleSheet("font-weight: bold; color: #e74c3c;")
            layout.addWidget(selection_info)
            
            def update_selection_count():
                selected_count = len(skill_list.selectedItems())
                selection_info.setText(f"Seçim: {selected_count} / {count}")
                if selected_count == count:
                    selection_info.setStyleSheet("font-weight: bold; color: #27ae60;")
                else:
                    selection_info.setStyleSheet("font-weight: bold; color: #e74c3c;")
            
            skill_list.itemSelectionChanged.connect(update_selection_count)
            
            # Butonlar
            button_layout = QHBoxLayout()
            
            cancel_btn = QPushButton("İptal")
            cancel_btn.clicked.connect(expertise_dialog.reject)
            button_layout.addWidget(cancel_btn)
            
            select_btn = QPushButton("Seç")
            select_btn.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    padding: 8px 16px;
                    font-weight: bold;
                    border-radius: 4px;
                }
                QPushButton:hover {
                    background-color: #229954;
                }
            """)
            
            def on_expertise_selected():
                selected_items = skill_list.selectedItems()
                if len(selected_items) != count:
                    QMessageBox.warning(expertise_dialog, "Uyarı", f"Lütfen tam olarak {count} skill seçin!")
                    return
                
                selected_skills = []
                for item in selected_items:
                    skill_name = item.text().split(" ✓")[0].split(" ⭐")[0].strip()
                    
                    # Proficient kontrolü
                    if skill_name not in proficient_skills:
                        QMessageBox.warning(expertise_dialog, "Uyarı", f"{skill_name} proficient değil! Expertise için skill proficient olmalı.")
                        return
                    
                    selected_skills.append(skill_name)
                
                # Expertise skill'lerini karaktere ekle
                if "skills" not in character_data:
                    character_data["skills"] = {}
                
                current_expertise = character_data["skills"].get("expertise", [])
                # Mevcut expertise'lere ekle (duplicate kontrolü)
                for skill in selected_skills:
                    if skill not in current_expertise:
                        current_expertise.append(skill)
                
                character_data["skills"]["expertise"] = current_expertise
                
                # Bekleyen seçimi kaldır
                pending_choices = character_data.get("pending_choices", [])
                filtered_choices = []
                for c in pending_choices:
                    c_type = str(c.get("type", "")).lower()
                    c_level = c.get("level")
                    choice_type = choice_data.get("type", "").lower()
                    choice_level = choice_data.get("level")
                    
                    if not (c_type == choice_type and c_level == choice_level):
                        filtered_choices.append(c)
                
                character_data["pending_choices"] = filtered_choices
                
                # Dosyaya kaydet
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(character_data, f, ensure_ascii=False, indent=2)
                
                QMessageBox.information(expertise_dialog, "Başarılı", 
                    f"Expertise seçildi: {', '.join(selected_skills)}\n\nBu skill'ler artık double proficiency bonus alacak!")
                expertise_dialog.accept()
                
                # Listeleri yenile
                self._refresh_current_character_info()
                self._refresh_pending_choices()
                if hasattr(self, '_update_character_preview'):
                    self._update_character_preview()
                if hasattr(self, '_update_character_stats'):
                    self._update_character_stats()
            
            select_btn.clicked.connect(on_expertise_selected)
            button_layout.addWidget(select_btn)
            
            layout.addLayout(button_layout)
            expertise_dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Expertise seçimi tamamlanırken hata oluştu:\n{str(e)}")
            import traceback
            print(f"Expertise seçim hatası: {traceback.format_exc()}")

    def _refresh_current_character_info(self):
        """Mevcut karakter bilgisini yenile"""
        try:
            if hasattr(self, 'current_character') and self.current_character:
                char_name = self.current_character.get('name', 'İsimsiz')
                char_level = self.current_character.get('level', 1)
                char_class = self.current_character.get('class', 'Sınıfsız')
                
                info_text = f"{char_name} - Seviye {char_level} {char_class}"
                self.current_character_label.setText(info_text)
                
                # Seviye bilgilerini güncelle
                self.current_level_label.setText(str(char_level))
                self.new_level_spin.setValue(char_level + 1)
                
                # HP artışını hesapla
                self._on_level_change()
                
                # Yeni seçenekleri güncelle
                self._refresh_available_feats()
                self._update_character_preview()
                self._refresh_pending_choices()
            else:
                self.current_character_label.setText("Henüz karakter oluşturulmadı")
                self.current_level_label.setText("1")
                self.new_level_spin.setValue(2)
                
        except Exception as e:
            print(f"Karakter bilgisi yenilenirken hata: {e}")

