    def _load_current_character_inventory(self):
        """Mevcut karakterin envanterini yükle"""
        try:
            if hasattr(self, 'current_character_file') and self.current_character_file:
                import json
                with open(self.current_character_file, 'r', encoding='utf-8') as f:
                    character_data = json.load(f)
                
                # Envanteri temizle
                self.inventory_list.clear()
                
                # Envanter eşyalarını yükle (filtreleme ile)
                # Filtreleme fonksiyonu otomatik olarak listeyi güncelleyecek
                self._filter_inventory_list()
                
                # Envanter özetini güncelle
                self._update_inventory_summary(character_data)
            else:
                # Karakter yoksa envanteri temizle
                self.inventory_list.clear()
                if hasattr(self, 'weight_label'):
                    self.weight_label.setText("⚖️ Ağırlık: 0 lb")
                if hasattr(self, 'carrying_capacity_label'):
                    self.carrying_capacity_label.setText("💪 Taşıma Kapasitesi: 0 lb")
                if hasattr(self, 'gold_label'):
                    self.gold_label.setText("💰 Altın: 0 gp")
                if hasattr(self, 'item_count_label'):
                    self.item_count_label.setText("📦 Eşya Sayısı: 0")
                if hasattr(self, 'total_value_label'):
                    self.total_value_label.setText("💎 Toplam Değer: 0 gp")
                if hasattr(self, 'category_breakdown_label'):
                    self.category_breakdown_label.setVisible(False)
                
        except Exception as e:
            print(f"Envanter yüklenemedi: {e}")
            import traceback
            print(traceback.format_exc())
    
    def _filter_inventory_list(self):
        """Envanter listesini filtrele (arama ve kategori) - DÜZELTİLDİ (Equipment GUI İyileştirme)"""
        try:
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                self.inventory_list.clear()
                return
            
            import json
            with open(self.current_character_file, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            equipment = character_data.get("equipment", [])
            search_text = self.inventory_search.text().lower() if hasattr(self, 'inventory_search') else ""
            filter_type = self.inventory_filter_combo.currentText() if hasattr(self, 'inventory_filter_combo') else "Tümü"
            
            # Filtreleme
            filtered_equipment = []
            for item in equipment:
                item_name = item.get('name', 'İsimsiz Eşya').lower()
                item_type = item.get('type', 'gear')
                category = item.get('category', '').lower()
                
                # Arama filtresi
                if search_text and search_text not in item_name and search_text not in category:
                    continue
                
                # Tip filtresi
                if filter_type != "Tümü":
                    type_map = {
                        "Silahlar": "weapon",
                        "Zırhlar": "armor",
                        "Macera Eşyaları": "gear",
                        "Diğer": "other"
                    }
                    if item_type != type_map.get(filter_type, ""):
                        continue
                
                filtered_equipment.append(item)
            
            # Listeyi güncelle
            self.inventory_list.clear()
            for item in filtered_equipment:
                item_name = item.get('name', 'İsimsiz Eşya')
                quantity = item.get('quantity', 1)
                category = item.get('category', '')
                
                # Eşya tipine göre ikon ekle
                if item.get('type') == 'weapon':
                    icon = "⚔️"
                elif item.get('type') == 'armor':
                    icon = "🛡️"
                elif item.get('type') == 'gear':
                    icon = "🎒"
                else:
                    icon = "📦"
                
                item_text = f"{icon} {item_name}"
                if quantity > 1:
                    item_text += f" x{quantity}"
                if category:
                    item_text += f" ({category})"
                
                self.inventory_list.addItem(item_text)
            
        except Exception as e:
            print(f"Envanter filtreleme hatası: {e}")
            import traceback
            print(traceback.format_exc())
    
    def _filter_category_lists(self):
        """Kategori listelerini filtrele (arama) - DÜZELTİLDİ (Equipment GUI İyileştirme)"""
        try:
            if not hasattr(self, 'category_search'):
                return
            
            search_text = self.category_search.text().lower()
            
            # Hangi sekme aktif?
            current_tab = self.categories_tabs.currentIndex()
            
            # Aktif sekmeye göre filtrele
            if current_tab == 0:  # Silahlar
                self._filter_list(self.weapons_list, search_text)
            elif current_tab == 1:  # Zırhlar
                self._filter_list(self.armor_list, search_text)
            elif current_tab == 2:  # Macera eşyaları
                sub_tab = self.adventure_gear_subtabs.currentIndex()
                if sub_tab == 0:  # Depolama
                    self._filter_list(self.storage_list, search_text)
                elif sub_tab == 1:  # Araçlar
                    self._filter_list(self.tools_list, search_text)
                elif sub_tab == 2:  # Büyü Odakları
                    self._filter_list(self.focus_list, search_text)
                elif sub_tab == 3:  # Giysiler
                    self._filter_list(self.clothing_list, search_text)
                elif sub_tab == 4:  # Diğer
                    self._filter_list(self.other_list, search_text)
            
        except Exception as e:
            print(f"Kategori filtreleme hatası: {e}")
            import traceback
            print(traceback.format_exc())
    
    def _filter_list(self, list_widget, search_text):
        """List widget'ı filtrele - DÜZELTİLDİ (Equipment GUI İyileştirme)"""
        try:
            if not search_text:
                # Tüm öğeleri göster
                for i in range(list_widget.count()):
                    item = list_widget.item(i)
                    item.setHidden(False)
            else:
                # Filtrele
                for i in range(list_widget.count()):
                    item = list_widget.item(i)
                    item_text = item.text().lower()
                    if search_text in item_text:
                        item.setHidden(False)
                    else:
                        item.setHidden(True)
        except Exception as e:
            print(f"Liste filtreleme hatası: {e}")

    def _populate_item_categories(self):
        """Eşya kategorilerini doldur"""
        try:
            # Silahlar
            weapons = self.data.get("equipment", {}).get("weapons", {})
            self.weapons_list.clear()
            for weapon_name, weapon_data in weapons.items():
                cost = weapon_data.get("cost", "0 gp")
                weight = weapon_data.get("weight", 0)
                damage = weapon_data.get("damage", "")
                item_text = f"{weapon_name} - {cost} ({weight} lb)"
                if damage:
                    item_text += f" - {damage}"
                self.weapons_list.addItem(item_text)
            
            # Zırhlar
            armor = self.data.get("equipment", {}).get("armor", {})
            self.armor_list.clear()
            for armor_name, armor_data in armor.items():
                cost = armor_data.get("cost", "0 gp")
                weight = armor_data.get("weight", 0)
                ac = armor_data.get("ac", "")
                item_text = f"{armor_name} - {cost} ({weight} lb)"
                if ac:
                    item_text += f" - AC {ac}"
                self.armor_list.addItem(item_text)
            
            # Macera eşyaları kategorilere ayır
            adventure_gear = self.data.get("equipment", {}).get("adventuring_gear", {})
        
            # Kategorileri temizle
            self.storage_list.clear()
            self.tools_list.clear()
            self.focus_list.clear()
            self.clothing_list.clear()
            self.other_list.clear()
            
            # Kategorilere göre eşyaları ayır
            for gear_name, gear_data in adventure_gear.items():
                cost = gear_data.get("cost", "0 gp")
                weight = gear_data.get("weight", 0)
                description = gear_data.get("description", "")
                item_text = f"{gear_name} - {cost} ({weight} lb)"
                
                # Kategori belirleme
                category = self._categorize_adventure_gear(gear_name, description)
                
                if category == "storage":
                    self.storage_list.addItem(item_text)
                elif category == "tools":
                    self.tools_list.addItem(item_text)
                elif category == "focus":
                    self.focus_list.addItem(item_text)
                elif category == "clothing":
                    self.clothing_list.addItem(item_text)
                else:
                    self.other_list.addItem(item_text)
                
        except Exception as e:
            print(f"Eşya kategorileri yüklenirken hata: {e}")

    def _categorize_adventure_gear(self, gear_name, description):
        """Macera eşyalarını kategorilere ayır"""
        gear_name_lower = gear_name.lower()
        description_lower = description.lower()
        
        # Depolama eşyaları
        storage_keywords = [
            "backpack", "bag", "barrel", "basket", "bottle", "bucket", 
            "chest", "case", "pouch", "sack", "vial", "flask", "tankard",
            "waterskin", "container", "storage"
        ]
        
        # Araçlar
        tools_keywords = [
            "hammer", "crowbar", "grappling", "block and tackle", "climber's kit",
            "fishing tackle", "healer's kit", "hunting trap", "ball bearings",
            "caltrops", "chain", "chalk", "rope", "lantern", "torch", "oil",
            "spike", "tinderbox", "tool", "kit", "lock", "pick", "shovel",
            "tent", "bedroll", "blanket", "bell", "candle", "lamp"
        ]
        
        # Büyü odakları
        focus_keywords = [
            "arcane focus", "druidic focus", "holy symbol", "component pouch",
            "crystal", "orb", "rod", "staff", "wand", "amulet", "emblem",
            "reliquary", "totem", "mistletoe", "yew"
        ]
        
        # Giysiler
        clothing_keywords = [
            "clothes", "costume", "fine", "common", "traveler", "clothing",
            "robe", "vest", "hat", "cap", "boots", "gloves"
        ]
        
        # Kontrol et
        for keyword in storage_keywords:
            if keyword in gear_name_lower or keyword in description_lower:
                return "storage"
        
        for keyword in tools_keywords:
            if keyword in gear_name_lower or keyword in description_lower:
                return "tools"
        
        for keyword in focus_keywords:
            if keyword in gear_name_lower or keyword in description_lower:
                return "focus"
        
        for keyword in clothing_keywords:
            if keyword in gear_name_lower or keyword in description_lower:
                return "clothing"
        
        # Diğer (varsayılan)
        return "other"

    def _show_item_categories(self):
        """Eşya kategorilerini göster"""
        if not hasattr(self, 'categories_tabs'):
            return
        
        # Kategoriler grubunu vurgula
        self.categories_tabs.setCurrentIndex(0)  # Silahlar sekmesine git
        
        # Bilgi mesajı göster
        from PySide6.QtWidgets import QMessageBox
        msg = QMessageBox()
        msg.setWindowTitle("Eşya Ekleme")
        msg.setText("Aşağıdaki kategorilerden bir eşya seçin ve 'Seçili Eşyayı Envantere Ekle' butonuna tıklayın.")
        msg.setInformativeText("• ⚔️ Silahlar sekmesinde silahlar\n• 🛡️ Zırhlar sekmesinde zırhlar\n• 🎒 Macera Eşyaları sekmesinde:\n  - 📦 Depolama eşyaları\n  - 🔧 Araçlar\n  - 🔮 Büyü Odakları\n  - 👕 Giysiler\n  - 🎯 Diğer")
        msg.exec()

    def _add_selected_item_from_category(self):
        """Seçili eşyayı envantere ekle"""
        try:
            # Hangi sekme aktif?
            current_tab = self.categories_tabs.currentIndex()
            
            if current_tab == 0:  # Silahlar
                selected_item = self.weapons_list.currentItem()
                item_data = self.data.get("equipment", {}).get("weapons", {})
            elif current_tab == 1:  # Zırhlar
                selected_item = self.armor_list.currentItem()
                item_data = self.data.get("equipment", {}).get("armor", {})
            elif current_tab == 2:  # Macera eşyaları
                # Alt sekme kontrolü
                sub_tab = self.adventure_gear_subtabs.currentIndex()
                if sub_tab == 0:  # Depolama
                    selected_item = self.storage_list.currentItem()
                elif sub_tab == 1:  # Araçlar
                    selected_item = self.tools_list.currentItem()
                elif sub_tab == 2:  # Büyü Odakları
                    selected_item = self.focus_list.currentItem()
                elif sub_tab == 3:  # Giysiler
                    selected_item = self.clothing_list.currentItem()
                elif sub_tab == 4:  # Diğer
                    selected_item = self.other_list.currentItem()
                else:
                    return
                
                item_data = self.data.get("equipment", {}).get("adventuring_gear", {})
            
            if not selected_item:
                from PySide6.QtWidgets import QMessageBox
                QMessageBox.warning(None, "Uyarı", "Lütfen eklemek istediğiniz eşyayı seçin!")
                return
            
            # Eşya adını parse et (format: "Eşya Adı - 10 gp (5 lb)")
            item_text = selected_item.text()
            item_name = item_text.split(" - ")[0]
            
            # Eşya verilerini al
            if item_name not in item_data:
                from PySide6.QtWidgets import QMessageBox
                QMessageBox.warning(None, "Hata", "Eşya verileri bulunamadı!")
                return
            
            item_info = item_data[item_name]
            
            # Miktar sor
            from PySide6.QtWidgets import QInputDialog
            quantity, ok = QInputDialog.getInt(None, "Miktar", f"{item_name} kaç adet eklemek istiyorsunuz?", 1, 1, 1000)
            
            if not ok:
                return
            
            # Mevcut karakter kontrolü
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                from PySide6.QtWidgets import QMessageBox
                QMessageBox.warning(None, "Uyarı", "Lütfen önce bir karakter oluşturun!")
                return
            
            character_file = self.current_character_file
            
            try:
                import json
                with open(character_file, 'r', encoding='utf-8') as f:
                    character_data = json.load(f)
            except:
                from PySide6.QtWidgets import QMessageBox
                QMessageBox.warning(None, "Hata", "Karakter dosyası yüklenemedi!")
                return
            
            # Yeni eşya oluştur
            new_item = {
                "name": item_name,
                "category": "Silah" if current_tab == 0 else "Zırh" if current_tab == 1 else "Macera Eşyası",
                "weight": item_info.get("weight", 0),
                "cost": item_info.get("cost", "0 gp"),
                "quantity": quantity
            }
            
            # Silah özellikleri
            if current_tab == 0:  # Silahlar
                new_item["damage"] = item_info.get("damage", "")
                new_item["properties"] = item_info.get("properties", "")
            
            # Zırh özellikleri
            elif current_tab == 1:  # Zırhlar
                new_item["ac"] = item_info.get("ac", "")
                new_item["armor_type"] = item_info.get("armor_type", "")
            
            # Macera eşyası özellikleri
            else:
                new_item["description"] = item_info.get("description", "")
            
            # Eşyayı karaktere ekle
            if "equipment" not in character_data:
                character_data["equipment"] = []
            
            character_data["equipment"].append(new_item)
            
            # Karakteri kaydet
            with open(character_file, 'w', encoding='utf-8') as f:
                json.dump(character_data, f, ensure_ascii=False, indent=2)
            
            # Envanteri yenile
            self._load_current_character_inventory()
            
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.information(None, "Başarılı", f"{item_name} x{quantity} envantere eklendi!")
            
        except Exception as e:
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.critical(None, "Hata", f"Eşya eklenirken hata oluştu: {e}")

    def _refresh_inventory_character_list(self):
        """Envanter karakter listesini yenile"""
        try:
            import os
            import json
            
            self.inventory_character_combo.clear()
            characters = []
            
            if os.path.exists("characters"):
                for filename in os.listdir("characters"):
                    if filename.endswith("_karakter.json"):
                        filepath = os.path.join("characters", filename)
                        try:
                            with open(filepath, 'r', encoding='utf-8') as f:
                                char_data = json.load(f)
                                char_name = char_data.get("name", "İsimsiz")
                                char_level = char_data.get("level", 1)
                                char_class = char_data.get("class", "")
                                display_name = f"{char_name} (Seviye {char_level} {char_class})"
                                self.inventory_character_combo.addItem(display_name, filepath)
                                characters.append((char_name, char_level, filepath))
                        except Exception as e:
                            print(f"Karakter dosyası okunamadı {filename}: {e}")
            
            if not characters:
                self.inventory_character_combo.addItem("Henüz karakter oluşturulmadı")
            
            # İlk karakteri seç ve envanteri yükle
            if characters:
                self.inventory_character_combo.setCurrentIndex(0)
                self._load_character_inventory()
                
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Karakter listesi yenilenemedi:\n{str(e)}")

    def _load_character_inventory(self):
        """Seçilen karakterin envanterini yükle"""
        try:
            current_index = self.inventory_character_combo.currentIndex()
            if current_index < 0:
                return
                
            filepath = self.inventory_character_combo.itemData(current_index)
            if not filepath:
                return
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
                
            # Envanter eşyalarını yükle (filtreleme ile)
            # _filter_inventory_list fonksiyonu listeyi güncelleyecek
            self.current_character_file = filepath  # Geçici olarak ayarla ki filtreleme çalışsın
            self._filter_inventory_list()
            self.current_character_file = filepath  # Kalıcı olarak ayarla
            
            # Envanter özetini güncelle
            self._update_inventory_summary(character_data)
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Envanter yüklenemedi:\n{str(e)}")

    def _update_inventory_summary(self, character_data):
        """Envanter özetini güncelle (gelişmiş istatistikler) - DÜZELTİLDİ (Equipment GUI İyileştirme)"""
        try:
            equipment = character_data.get("equipment", [])
            total_weight = 0
            total_value = 0  # Eşyaların toplam değeri
            item_count = 0
            category_breakdown = {
                "weapon": {"count": 0, "weight": 0, "value": 0},
                "armor": {"count": 0, "weight": 0, "value": 0},
                "gear": {"count": 0, "weight": 0, "value": 0},
                "other": {"count": 0, "weight": 0, "value": 0}
            }
            
            for item in equipment:
                # Ağırlık hesaplama
                weight = item.get('weight', 0)
                quantity = item.get('quantity', 1)
                total_weight += weight * quantity
                item_count += quantity
                
                # Değer hesaplama - cost field'ından parse et
                cost_str = item.get('cost', '0 gp')
                item_value = 0
                try:
                    # "10 gp", "5 sp" gibi formatları parse et
                    if 'gp' in cost_str:
                        gold_value = float(cost_str.replace('gp', '').strip())
                        item_value = gold_value * quantity
                    elif 'sp' in cost_str:
                        silver_value = float(cost_str.replace('sp', '').strip())
                        item_value = (silver_value / 10) * quantity  # 10 sp = 1 gp
                    elif 'cp' in cost_str:
                        copper_value = float(cost_str.replace('cp', '').strip())
                        item_value = (copper_value / 100) * quantity  # 100 cp = 1 gp
                except:
                    pass  # Parse edilemeyen değerleri görmezden gel
                
                total_value += item_value
                
                # Kategori breakdown
                item_type = item.get('type', 'other')
                if item_type in category_breakdown:
                    category_breakdown[item_type]["count"] += quantity
                    category_breakdown[item_type]["weight"] += weight * quantity
                    category_breakdown[item_type]["value"] += item_value
            
            # Encumbrance details hesaplama - İYİLEŞTİRİLDİ (Encumbrance Details)
            from utils.calculations import calculate_encumbrance_details, check_attunement_limit
            
            encumbrance_info = calculate_encumbrance_details(character_data)
            total_weight = encumbrance_info.get("total_weight", 0)
            base_capacity = encumbrance_info.get("base_capacity", 0)
            encumbered_threshold = encumbrance_info.get("encumbered_threshold", 0)
            heavily_encumbered_threshold = encumbrance_info.get("heavily_encumbered_threshold", 0)
            encumbrance_status = encumbrance_info.get("encumbrance_status", "unencumbered")
            movement_penalty = encumbrance_info.get("movement_penalty", 0)
            remaining_capacity = encumbrance_info.get("remaining_capacity", 0)
            percentage_used = encumbrance_info.get("percentage_used", 0)
            
            # Attunement tracking - İYİLEŞTİRİLDİ (Attunement Tracking)
            attunement_info = check_attunement_limit(character_data)
            current_attuned = attunement_info.get("current_attuned", 0)
            max_attuned = attunement_info.get("max_attuned", 3)
            remaining_slots = attunement_info.get("remaining_slots", 3)
            can_attune_more = attunement_info.get("can_attune_more", True)
            
            # İstatistikleri güncelle
            if hasattr(self, 'weight_label'):
                weight_text = f"⚖️ Ağırlık: {total_weight:.1f} lb / {base_capacity} lb ({percentage_used:.1f}%)"
                self.weight_label.setText(weight_text)
                
                # Encumbrance status'a göre renk
                if encumbrance_status == "heavily_encumbered":
                    self.weight_label.setStyleSheet("font-weight: bold; color: #e74c3c; font-size: 11px;")
                    weight_text += f" [Ağır Yüklü: -20 ft]"
                elif encumbrance_status == "encumbered":
                    self.weight_label.setStyleSheet("font-weight: bold; color: #f39c12; font-size: 11px;")
                    weight_text += f" [Yüklü: -10 ft]"
                elif encumbrance_status == "at_capacity":
                    self.weight_label.setStyleSheet("font-weight: bold; color: #f1c40f; font-size: 11px;")
                else:
                    self.weight_label.setStyleSheet("font-weight: bold; color: #27ae60; font-size: 11px;")
                self.weight_label.setText(weight_text)
            
            if hasattr(self, 'carrying_capacity_label'):
                capacity_text = f"💪 Taşıma: {base_capacity} lb | Yüklü: {encumbered_threshold} lb | Ağır: {heavily_encumbered_threshold} lb"
                self.carrying_capacity_label.setText(capacity_text)
            
            # Encumbrance status label - İYİLEŞTİRİLDİ (yeni label)
            if hasattr(self, 'encumbrance_status_label'):
                status_texts = {
                    "unencumbered": "✅ Yüksüz",
                    "at_capacity": "⚠️ Kapasite Dolu",
                    "encumbered": "⚠️ Yüklü (-10 ft movement)",
                    "heavily_encumbered": "❌ Ağır Yüklü (-20 ft movement)"
                }
                status_text = status_texts.get(encumbrance_status, "Bilinmiyor")
                if movement_penalty < 0:
                    status_text += f" ({movement_penalty} ft)"
                self.encumbrance_status_label.setText(f"📦 Durum: {status_text}")
                
                # Status'a göre renk
                if encumbrance_status == "heavily_encumbered":
                    self.encumbrance_status_label.setStyleSheet("font-weight: bold; color: #e74c3c; font-size: 11px;")
                elif encumbrance_status == "encumbered":
                    self.encumbrance_status_label.setStyleSheet("font-weight: bold; color: #f39c12; font-size: 11px;")
                elif encumbrance_status == "at_capacity":
                    self.encumbrance_status_label.setStyleSheet("font-weight: bold; color: #f1c40f; font-size: 11px;")
                else:
                    self.encumbrance_status_label.setStyleSheet("font-weight: bold; color: #27ae60; font-size: 11px;")
            
            # Karakterin altın miktarını da kontrol et
            character_gold = character_data.get("gold", 0) or 0
            if hasattr(self, 'gold_label'):
                self.gold_label.setText(f"💰 Altın: {character_gold} gp")
            
            if hasattr(self, 'item_count_label'):
                self.item_count_label.setText(f"📦 Eşya Sayısı: {item_count}")
            
            if hasattr(self, 'total_value_label'):
                self.total_value_label.setText(f"💎 Toplam Eşya Değeri: {total_value:.2f} gp")
            
            # Attunement tracking güncelle - İYİLEŞTİRİLDİ (Attunement Tracking)
            if hasattr(self, 'attunement_label'):
                attunement_text = f"🔮 Attunement: {current_attuned}/{max_attuned}"
                if remaining_slots > 0:
                    attunement_text += f" ({remaining_slots} slot kaldı)"
                else:
                    attunement_text += " [LİMİT DOLU]"
                
                self.attunement_label.setText(attunement_text)
                
                # Attunement limit'e göre renk
                if not can_attune_more:
                    self.attunement_label.setStyleSheet("font-weight: bold; color: #e74c3c; font-size: 11px;")
                elif remaining_slots == 1:
                    self.attunement_label.setStyleSheet("font-weight: bold; color: #f39c12; font-size: 11px;")
                else:
                    self.attunement_label.setStyleSheet("font-weight: bold; color: #9b59b6; font-size: 11px;")
            
            # Kategori breakdown (detaylı istatistikler)
            if hasattr(self, 'category_breakdown_label'):
                breakdown_parts = []
                type_names = {
                    "weapon": "Silahlar",
                    "armor": "Zırhlar",
                    "gear": "Macera Eşyaları",
                    "other": "Diğer"
                }
                
                for item_type, stats in category_breakdown.items():
                    if stats["count"] > 0:
                        breakdown_parts.append(
                            f"{type_names.get(item_type, item_type)}: {stats['count']} adet, "
                            f"{stats['weight']} lb, {stats['value']:.2f} gp"
                        )
                
                if breakdown_parts:
                    breakdown_text = "📊 Detay: " + " | ".join(breakdown_parts)
                    self.category_breakdown_label.setText(breakdown_text)
                    self.category_breakdown_label.setVisible(True)
                else:
                    self.category_breakdown_label.setVisible(False)
            
        except Exception as e:
            print(f"Envanter özeti güncellenemedi: {e}")
            import traceback
            print(traceback.format_exc())

    def _show_item_details(self, item):
        """Seçili eşyanın detaylarını göster"""
        try:
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                return
                
            filepath = self.current_character_file
                
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
                
            equipment = character_data.get("equipment", [])
            item_index = self.inventory_list.row(item)
            
            if 0 <= item_index < len(equipment):
                item_data = equipment[item_index]
                
                # Eşya adı ve ikon
                item_name = item_data.get('name', 'İsimsiz Eşya')
                item_type = item_data.get('type', 'gear')
                
                # İkon belirleme
                if item_type == 'weapon':
                    icon = "⚔️"
                elif item_type == 'armor':
                    icon = "🛡️"
                else:
                    icon = "🎒"
                
                details = f"<h3>{icon} {item_name}</h3><br>"
                
                # Temel bilgiler
                details += "<b>📋 Temel Bilgiler:</b><br>"
                
                if 'category' in item_data:
                    details += f"• <b>Kategori:</b> {item_data['category']}<br>"
                
                if 'cost' in item_data:
                    details += f"• <b>Değer:</b> {item_data['cost']}<br>"
                
                if 'weight' in item_data:
                    weight = item_data['weight']
                    total_weight = weight * item_data.get('quantity', 1)
                    details += f"• <b>Ağırlık:</b> {weight} lb (Toplam: {total_weight} lb)<br>"
                
                if 'quantity' in item_data:
                    details += f"• <b>Miktar:</b> {item_data['quantity']}<br>"
                
                details += "<br>"
                
                # Eşya tipine göre özel bilgiler
                if item_type == 'weapon':
                    details += "<b>⚔️ Silah Bilgileri:</b><br>"
                    
                    if 'damage' in item_data:
                        details += f"• <b>Hasar:</b> {item_data['damage']}<br>"
                    
                    if 'versatile_damage' in item_data and item_data['versatile_damage']:
                        details += f"• <b>Çok Amaçlı Hasar:</b> {item_data['versatile_damage']}<br>"
                    
                    if 'weapon_type' in item_data:
                        weapon_type_tr = {"melee": "Yakın Dövüş", "ranged": "Uzak Dövüş"}
                        details += f"• <b>Tür:</b> {weapon_type_tr.get(item_data['weapon_type'], item_data['weapon_type'])}<br>"
                    
                    if 'range' in item_data and item_data['range']:
                        details += f"• <b>Menzil:</b> {item_data['range']}<br>"
                    
                    if 'thrown' in item_data:
                        thrown_tr = "Evet" if item_data['thrown'] else "Hayır"
                        details += f"• <b>Fırlatılabilir:</b> {thrown_tr}<br>"
                    
                    if 'properties' in item_data and item_data['properties']:
                        properties = item_data['properties']
                        if isinstance(properties, list):
                            properties_tr = {
                                "Light": "Hafif", "Heavy": "Ağır", "Finesse": "Çeviklik", 
                                "Two-handed": "İki Elle", "Versatile": "Çok Amaçlı",
                                "Ammunition": "Cephane", "Loading": "Yükleme",
                                "Reach": "Uzun Menzil", "Thrown": "Fırlatılabilir"
                            }
                            properties_display = [properties_tr.get(p, p) for p in properties]
                            details += f"• <b>Özellikler:</b> {', '.join(properties_display)}<br>"
                
                elif item_type == 'armor':
                    details += "<b>🛡️ Zırh Bilgileri:</b><br>"
                    
                    if 'ac' in item_data:
                        details += f"• <b>Zırh Sınıfı:</b> {item_data['ac']}<br>"
                    
                    if 'armor_type' in item_data:
                        armor_type_tr = {
                            "light": "Hafif Zırh", "medium": "Orta Zırh", 
                            "heavy": "Ağır Zırh", "shield": "Kalkan"
                        }
                        details += f"• <b>Zırh Türü:</b> {armor_type_tr.get(item_data['armor_type'], item_data['armor_type'])}<br>"
                    
                    if 'max_dex' in item_data and item_data['max_dex'] is not None:
                        details += f"• <b>Maksimum Çeviklik Bonusu:</b> +{item_data['max_dex']}<br>"
                    
                    if 'stealth_disadvantage' in item_data:
                        stealth_tr = "Evet" if item_data['stealth_disadvantage'] else "Hayır"
                        details += f"• <b>Gizlilik Dezavantajı:</b> {stealth_tr}<br>"
                
                else:  # gear/macera eşyası
                    details += "<b>🎒 Macera Eşyası Bilgileri:</b><br>"
                    
                    if 'description' in item_data:
                        details += f"• <b>Açıklama:</b> {item_data['description']}<br>"
                    
                    if 'type' in item_data and item_data['type'] != 'gear':
                        details += f"• <b>Tür:</b> {item_data['type']}<br>"
                
                # Magic item bonusları - İYİLEŞTİRİLDİ (Magic Item Bonuses)
                from utils.calculations import extract_magic_item_ac_bonus, extract_magic_item_bonus
                
                magic_ac_bonus = extract_magic_item_ac_bonus(item_data)
                is_attuned = item_data.get("attuned", False) or item_name in character_data.get("attuned_items", [])
                
                attack_bonus = 0
                damage_bonus = 0
                
                if item_type == "weapon":
                    attack_bonus = extract_magic_item_bonus(item_data, "attack")
                    damage_bonus = extract_magic_item_bonus(item_data, "damage")
                
                if magic_ac_bonus > 0 or attack_bonus > 0 or damage_bonus > 0 or is_attuned or item_name.lower().find("magic") != -1:
                    details += "<br><b>✨ Magic Item Özellikleri:</b><br>"
                    
                    if magic_ac_bonus > 0:
                        details += f"• <b>AC Bonus:</b> +{magic_ac_bonus}<br>"
                    
                    if attack_bonus > 0:
                        details += f"• <b>Attack Bonus:</b> +{attack_bonus}<br>"
                    if damage_bonus > 0:
                        details += f"• <b>Damage Bonus:</b> +{damage_bonus}<br>"
                    
                    # Attunement durumu
                    if is_attuned:
                        details += f"• <span style='color: #9b59b6; font-weight: bold;'>🔮 Attuned: Evet</span><br>"
                    elif magic_ac_bonus > 0 or attack_bonus > 0:
                        # Magic item ama attuned değil
                        from utils.calculations import can_attune_item
                        can_attune, reason = can_attune_item(character_data, item_name)
                        if can_attune:
                            details += f"• <span style='color: #3498db;'>🔮 Attune edilebilir ({reason})</span><br>"
                        else:
                            details += f"• <span style='color: #e74c3c;'>🔮 Attune edilemez ({reason})</span><br>"
                
                # Ek bilgiler
                details += "<br><b>📝 Notlar:</b><br>"
                details += "• Eşya karakterinizin envanterinde bulunmaktadır<br>"
                details += "• Eşyayı çıkarmak için 'Eşya Çıkar' butonunu kullanın<br>"
                details += "• Miktarını değiştirmek için eşyayı yeniden ekleyin<br>"
                if item_type in ["weapon", "armor"]:
                    details += "• Karşılaştırma için 'Item Karşılaştır' butonunu kullanın<br>"
                if is_attuned or (magic_ac_bonus > 0 or (item_type == "weapon" and extract_magic_item_bonus(item_data, "attack") > 0)):
                    details += "• Attunement için 'Attune Et/Çöz' butonunu kullanın"
                
                self.item_details_text.setHtml(details)
                
                # Item'ı sakla karşılaştırma için - İYİLEŞTİRİLDİ (Equipment Comparison)
                if not hasattr(self, 'selected_item_for_comparison'):
                    self.selected_item_for_comparison = None
                
                # İlk seçilen item'ı sakla, ikinci seçimde karşılaştır
                if self.selected_item_for_comparison is None:
                    self.selected_item_for_comparison = item_data
                else:
                    # İkinci item seçildi, karşılaştırmayı göster
                    pass
            
        except Exception as e:
            print(f"Eşya detayları gösterilemedi: {e}")

    def _show_equipment_comparison_dialog(self):
        """Equipment karşılaştırma dialog'unu göster - İYİLEŞTİRİLDİ (Equipment Comparison)"""
        try:
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Önce bir karakter yükleyin!")
                return
            
            import json
            with open(self.current_character_file, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            from gui.equipment_comparison_dialog import EquipmentComparisonDialog
            
            dialog = EquipmentComparisonDialog(self, character_data, self.data)
            dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Karşılaştırma dialog'u açılırken hata oluştu:\n{str(e)}")
            import traceback
            print(traceback.format_exc())

    def _toggle_item_attunement(self):
        """Item attunement durumunu değiştir - İYİLEŞTİRİLDİ (Attunement Tracking)"""
        try:
            current_item = self.inventory_list.currentItem()
            if not current_item:
                QMessageBox.warning(self, "Uyarı", "Attune etmek için bir item seçin!")
                return
            
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Önce bir karakter yükleyin!")
                return
            
            filepath = self.current_character_file
            
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
            
            equipment = character_data.get("equipment", [])
            item_index = self.inventory_list.row(current_item)
            
            if 0 <= item_index < len(equipment):
                item_data = equipment[item_index]
                item_name = item_data.get("name", "")
                
                # Attunement kontrolü
                from utils.calculations import can_attune_item, check_attunement_limit
                
                attuned_items = character_data.get("attuned_items", [])
                is_attuned = item_data.get("attuned", False) or item_name in attuned_items
                
                if is_attuned:
                    # Attunement'i çöz
                    item_data["attuned"] = False
                    if item_name in attuned_items:
                        attuned_items.remove(item_name)
                        character_data["attuned_items"] = attuned_items
                    
                    QMessageBox.information(self, "Başarılı", f"{item_name} attunement'i çözüldü.")
                else:
                    # Attune et
                    can_attune, reason = can_attune_item(character_data, item_name)
                    
                    if not can_attune:
                        QMessageBox.warning(self, "Uyarı", f"{item_name} attune edilemez:\n{reason}")
                        return
                    
                    item_data["attuned"] = True
                    if "attuned_items" not in character_data:
                        character_data["attuned_items"] = []
                    if item_name not in character_data["attuned_items"]:
                        character_data["attuned_items"].append(item_name)
                    
                    attunement_info = check_attunement_limit(character_data)
                    QMessageBox.information(self, "Başarılı", 
                        f"{item_name} attune edildi.\nAttunement: {attunement_info['current_attuned']}/{attunement_info['max_attuned']} "
                        f"({attunement_info['remaining_slots']} slot kaldı)")
                
                # Karakter dosyasını kaydet
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(character_data, f, ensure_ascii=False, indent=2)
                
                # UI'ı güncelle
                self._load_current_character_inventory()
                if hasattr(self, '_update_inventory_summary'):
                    self._update_inventory_summary(character_data)
                
                # Item detaylarını yeniden göster
                self._show_item_details(current_item)
                
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Attunement değiştirilirken hata oluştu:\n{str(e)}")
            import traceback
            print(traceback.format_exc())

    def _remove_item(self):
        """Seçili eşyayı çıkar"""
        try:
            current_item = self.inventory_list.currentItem()
            if not current_item:
                QMessageBox.warning(self, "Uyarı", "Çıkarmak için bir eşya seçin!")
                return
            
            if not hasattr(self, 'current_character_file') or not self.current_character_file:
                QMessageBox.warning(self, "Uyarı", "Lütfen önce bir karakter oluşturun!")
                return
                
            filepath = self.current_character_file
            
            # Onay dialog'u
            reply = QMessageBox.question(self, "Eşya Çıkar", 
                "Bu eşyayı envanterden çıkarmak istediğinizden emin misiniz?",
                QMessageBox.Yes | QMessageBox.No)
            
            if reply != QMessageBox.Yes:
                return
            
            # Karakter dosyasını güncelle
            import json
            with open(filepath, 'r', encoding='utf-8') as f:
                character_data = json.load(f)
                
            equipment = character_data.get("equipment", [])
            item_index = self.inventory_list.row(current_item)
            
            if 0 <= item_index < len(equipment):
                removed_item = equipment.pop(item_index)
                
                # Dosyaya kaydet
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(character_data, f, ensure_ascii=False, indent=2)
                
            # Envanteri yenile
            self._load_current_character_inventory()
                
            QMessageBox.information(self, "Başarılı", f"{removed_item.get('name', 'Eşya')} çıkarıldı!")
            
        except Exception as e:
            QMessageBox.critical(self, "Hata", f"Eşya çıkarılamadı:\n{str(e)}")

    def _init_advanced_ui(self):
        """Gelişmiş özellikler UI'sını oluştur (opsiyonel)"""
        outer_layout = self.advanced_layout
        
        scroll_area = QScrollArea()
