class PathfinderPage(QWidget):
    SYSTEM_NAME = "PATHFINDER_1E"
    
    def __init__(self):
        super().__init__()
        try:
            self.data = load_pathfinder_1e_data(APP_BASE_DIR)
        except Exception as e:
            QMessageBox.warning(None, "Uyarı", f"Pathfinder 1e verileri yüklenemedi: {e}\nLütfen data/pathfinder_1e_data.json dosyasının mevcut olduğundan emin olun.")
            self.data = {"races": {}, "classes": {}, "feats": {}, "spells": {}, "items": {}}
        
        self.current_character = None
        self.inventory_items = []
        self._rules_cache = None
        self.current_character_image_data = None
        self.current_step = 0
        self._current_race_bonus: dict[str, int] = {}
        
        # Pathfinder 1e karakter oluşturma adımları
        self.steps = [
            {"name": "İsim ve Sınıf", "description": "Karakterinizin ismini ve sınıfını seçin"},
            {"name": "Irk", "description": "Karakterinizin ırkını seçin"},
            {"name": "Yetenek Puanları", "description": "Point-buy sistemi ile yetenek puanlarınızı dağıtın"},
            {"name": "Sınıf Becerileri", "description": "Sınıfınıza özel becerileri seçin"},
            {"name": "Feat'ler", "description": "İsteğe bağlı feat'leri seçin"},
            {"name": "Büyüler", "description": "Büyücü sınıflar için büyü seçimi (Not: Büyüler henüz çekilemedi)"},
            {"name": "Ekipman", "description": "Başlangıç ekipmanınızı seçin"},
            {"name": "Kişilik", "description": "Karakterinizin kişilik ve fiziksel özelliklerini belirleyin"},
            {"name": "Özet", "description": "Karakterinizin özetini görüntüleyin ve tamamlayın"}
        ]
        self._init_ui()
    
    def _init_ui(self):
        """Pathfinder 1e UI'sını başlat - DndPage'e benzer adım bazlı yapı"""
        # Ana layout
        layout = QVBoxLayout(self)
        layout.setContentsMargins(5, 5, 5, 5)
        layout.setSpacing(2)
        
        # Header
        header_widget = QWidget()
        header_widget.setStyleSheet("background-color: #34495e; border-radius: 10px; margin: 5px;")
        header_widget.setMaximumHeight(140)
        header_layout = QHBoxLayout(header_widget)
        header_layout.setContentsMargins(10, 5, 10, 5)
        header_layout.addStretch()
        
        title = QLabel("Diyargezer - Pathfinder 1e Karakter Oluşturucu")
        title.setStyleSheet("font-size: 20px; font-weight: bold; color: white; margin: 5px;")
        title.setAlignment(Qt.AlignCenter)
        title.setWordWrap(True)
        header_layout.addWidget(title)
        header_layout.addStretch()
        layout.addWidget(header_widget)
        
        # Toolbar
        toolbar_widget = self._build_toolbar()
        toolbar_widget.setMaximumHeight(40)
        layout.addWidget(toolbar_widget)
        
        # Tab widget (DndPage gibi)
        self.tab_widget = QtWidgets.QTabWidget()
        self.tab_widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        layout.addWidget(self.tab_widget, 1)
        
        # Karakter oluşturma sekmesi
        self.character_tab = QWidget()
        self.character_layout = QVBoxLayout(self.character_tab)
        self.character_layout.setContentsMargins(0, 0, 0, 0)
        self.character_layout.setSpacing(0)
        self.tab_widget.addTab(self.character_tab, "🎭 Karakter")
        
        # Karakter oluşturma UI'sını oluştur (adım bazlı)
        self._init_character_ui()
    
    def _init_character_ui(self):
        """Pathfinder 1e karakter oluşturma UI'sını oluştur - Adım bazlı yapı (DndPage'e benzer)"""
        # Ana splitter oluştur (sol: adım listesi, orta: içerik, sağ: açıklama)
        main_splitter = QtWidgets.QSplitter(Qt.Horizontal)
        main_splitter.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        
        # Sol panel: Adım listesi
        self.step_list_widget = QWidget()
        step_list_layout = QVBoxLayout(self.step_list_widget)
        step_list_layout.setContentsMargins(10, 10, 10, 10)
        
        step_list_title = QLabel("Adımlar")
        step_list_title.setStyleSheet("font-size: 16px; font-weight: bold; color: #2c3e50; margin-bottom: 10px;")
        step_list_layout.addWidget(step_list_title)
        
        self.step_list = QListWidget()
        self.step_list.setMaximumWidth(200)
        self.step_list.setStyleSheet("""
            QListWidget {
                border: 1px solid #dee2e6;
                border-radius: 5px;
                background-color: #f8f9fa;
            }
            QListWidget::item {
                padding: 8px;
                border-bottom: 1px solid #dee2e6;
            }
            QListWidget::item:selected {
                background-color: #3498db;
                color: white;
            }
            QListWidget::item:hover {
                background-color: #e9ecef;
            }
        """)
        self.step_items = []
        for i, step in enumerate(self.steps):
            item_text = f"{i+1}. {step['name']}"
            item = QListWidgetItem(item_text)
            self.step_list.addItem(item)
            self.step_items.append(item)
        self.step_list.setCurrentRow(0)
        self.step_list.currentRowChanged.connect(self._on_step_changed)
        step_list_layout.addWidget(self.step_list)
        
        # Orta panel: Adım içeriği (StackedWidget)
        self.step_stack = QStackedWidget()
        self.step_widgets = []
        
        # Her adım için widget oluştur
        for i, step in enumerate(self.steps):
            step_widget = QWidget()
            step_layout = QVBoxLayout(step_widget)
            step_layout.setContentsMargins(10, 10, 10, 10)
            
            scroll = QScrollArea()
            scroll.setWidgetResizable(True)
            
            content_widget = QWidget()
            content_layout = QVBoxLayout(content_widget)
            content_layout.setSpacing(15)
            
            # Adım başlığı
            step_title = QLabel(step['name'])
            step_title.setStyleSheet("font-size: 20px; font-weight: bold; color: #2c3e50; margin-bottom: 10px;")
            content_layout.addWidget(step_title)
            
            # Adım açıklaması
            step_desc = QLabel(step['description'])
            step_desc.setStyleSheet("font-size: 14px; color: #7f8c8d; margin-bottom: 15px;")
            step_desc.setWordWrap(True)
            content_layout.addWidget(step_desc)
            
            # Placeholder - gerçek içerik _populate_step_widgets'te oluşturulacak
            placeholder = QLabel(f"{step['name']} içeriği buraya gelecek")
            placeholder.setStyleSheet("color: #95a5a6; font-style: italic;")
            content_layout.addWidget(placeholder)
            content_layout.addStretch()
            
            scroll.setWidget(content_widget)
            step_layout.addWidget(scroll)
            
            # İleri/Geri butonları
            nav_layout = QHBoxLayout()
            back_btn = QPushButton("← Geri")
            back_btn.setEnabled(i > 0)
            back_btn.clicked.connect(lambda checked, idx=i: self._go_to_step(idx - 1))
            next_btn = QPushButton("İleri →")
            if i == len(self.steps) - 1:
                next_btn.setText("Tamamla")
                next_btn.clicked.connect(self._complete_character)
            else:
                next_btn.clicked.connect(lambda checked, idx=i: self._go_to_step(idx + 1))
            
            nav_layout.addWidget(back_btn)
            nav_layout.addStretch()
            nav_layout.addWidget(next_btn)
            step_layout.addLayout(nav_layout)
            
            self.step_stack.addWidget(step_widget)
            self.step_widgets.append(content_widget)
        
        # Sağ panel: Açıklama paneli
        self.info_panel = QWidget()
        info_layout = QVBoxLayout(self.info_panel)
        
        info_title = QLabel("Seçim Açıklaması")
        info_title.setStyleSheet("font-size: 18px; font-weight: bold; color: #ecf0f1; margin: 10px;")
        info_title.setAlignment(Qt.AlignCenter)
        info_layout.addWidget(info_title)
        
        self.info_text = QTextEdit()
        self.info_text.setReadOnly(True)
        self.info_text.setStyleSheet("""
            QTextEdit {
                background-color: #2c3e50;
                color: #ecf0f1;
                border: 2px solid #34495e;
                border-radius: 5px;
                padding: 10px;
                font-size: 14px;
            }
        """)
        self.info_text.setPlaceholderText("Bir seçim yapın, açıklaması burada görünecek...")
        info_layout.addWidget(self.info_text)
        
        # Splitter'a panelleri ekle
        main_splitter.addWidget(self.step_list_widget)
        main_splitter.addWidget(self.step_stack)
        main_splitter.addWidget(self.info_panel)
        main_splitter.setSizes([200, 600, 300])
        main_splitter.setChildrenCollapsible(False)
        
        # Character tab'a splitter'ı ekle
        self.character_layout.addWidget(main_splitter, 1)
        
        # Adım widget'larını doldur
        self._populate_step_widgets()
        
        # İlk adımı göster
        self._go_to_step(0)
    
    def _on_step_changed(self, new_index: int):
        """Adım listesinden adım değiştiğinde çağrılır"""
        if 0 <= new_index < len(self.steps):
            self._go_to_step(new_index)
    
    def _go_to_step(self, step_index: int):
        """Belirtilen adıma git"""
        if step_index < 0 or step_index >= len(self.steps):
            return
        
        if not hasattr(self, 'step_stack') or not hasattr(self, 'step_list') or not hasattr(self, 'info_text'):
            return
        
        # Validasyon yap (eğer ileri gidiyorsak)
        if step_index > self.current_step:
            if not self._validate_current_step():
                return
        
        self.current_step = step_index
        
        try:
            if self.step_stack.count() > step_index:
                self.step_stack.setCurrentIndex(step_index)
            if self.step_list.count() > step_index:
                self.step_list.setCurrentRow(step_index)
            
            # Adım açıklamasını güncelle
            step = self.steps[step_index]
            self.info_text.setText(f"<b>{step['name']}</b><br><br>{step['description']}")
        except (AttributeError, RuntimeError):
            return
        
        # Özet adımına gelindiğinde güncelle
        if step['name'] == "Özet":
            try:
                self._update_summary_step()
            except Exception as e:
                print(f"Özet güncelleme hatası: {e}")
    
    def _validate_current_step(self) -> bool:
        """Mevcut adımın geçerliliğini kontrol et"""
        # Temel validasyon - ileride genişletilebilir
        if self.current_step == 0:  # İsim ve Sınıf
            if not self.current_character or not self.current_character.get('name') or not self.current_character.get('class'):
                QMessageBox.warning(self, "Uyarı", "Lütfen önce bir karakter oluşturun.")
                return False
        return True
    
    def _populate_step_widgets(self):
        """Her adım için widget içeriğini doldur - Pathfinder 1e için"""
        # Önce temel widget'ları oluştur (eğer yoksa)
        if not hasattr(self, 'ability_spins'):
            self._build_basic_widgets()
        
        # Her adım için içeriği doldur
        for i, step in enumerate(self.steps):
            if i >= len(self.step_widgets):
                continue
            
            layout = self.step_widgets[i].layout()
            if not layout:
                continue
            
            # Placeholder ve daha önce eklenen widget'ları kaldır (başlık ve açıklama korunur)
            # Layout'ta başlık (0) ve açıklama (1) var, placeholder (2) ve diğer widget'lar (2+) kaldırılacak
            widgets_to_remove = []
            for j in reversed(range(layout.count())):
                # İlk 2 widget'ı koru (başlık ve açıklama)
                if j < 2:
                    continue
                
                item = layout.itemAt(j)
                if item:
                    widget = item.widget()
                    if widget:
                        try:
                            # Placeholder veya daha önce eklenen widget'ları kaldır
                            if isinstance(widget, QLabel):
                                widget_text = widget.text()
                                if "içeriği buraya gelecek" in widget_text or "yakında eklenecek" in widget_text:
                                    widgets_to_remove.append(widget)
                            elif isinstance(widget, (QGroupBox, QWidget)):
                                # Daha önce eklenen widget'ları kaldır
                                widgets_to_remove.append(widget)
                        except (RuntimeError, AttributeError):
                            continue
            
            # Widget'ları güvenli şekilde kaldır
            for widget in widgets_to_remove:
                try:
                    layout.removeWidget(widget)
                    widget.setParent(None)
                    widget.deleteLater()
                except (RuntimeError, AttributeError):
                    pass
            
            # Adım 0: İsim ve Sınıf
            if step['name'] == "İsim ve Sınıf":
                name_class_group = QGroupBox("Karakter Bilgileri")
                name_class_layout = QVBoxLayout()
                name_class_layout.setContentsMargins(5, 5, 5, 5)
                name_class_layout.setSpacing(6)
                
                name_label = QLabel("İsim:")
                name_edit = QLineEdit()
                name_edit.setMaximumHeight(32)
                if self.current_character:
                    name_edit.setText(self.current_character.get('name', ''))
                    name_edit.setReadOnly(True)  # İlk dialog'da zaten girildi
                name_class_layout.addWidget(name_label)
                name_class_layout.addWidget(name_edit)
                
                class_label = QLabel("Sınıf:")
                class_combo = QComboBox()
                classes = sorted(self.data.get("classes", {}).keys())
                class_combo.addItems(classes if classes else ["Sınıf bulunamadı"])
                if self.current_character:
                    char_class = self.current_character.get('class', '')
                    idx = class_combo.findText(char_class)
                    if idx >= 0:
                        class_combo.setCurrentIndex(idx)
                    class_combo.setEnabled(False)  # İlk dialog'da zaten seçildi
                class_combo.setMaximumHeight(32)
                name_class_layout.addWidget(class_label)
                name_class_layout.addWidget(class_combo)
                
                name_class_group.setLayout(name_class_layout)
                name_class_group.setMaximumHeight(180)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                # Eğer layout.count() < 2 ise, addWidget kullan
                if layout.count() >= 2:
                    layout.insertWidget(2, name_class_group)
                else:
                    layout.addWidget(name_class_group)
            
            # Adım 1: Irk
            elif step['name'] == "Irk":
                race_group = QGroupBox("Irk Seçimi")
                race_layout = QVBoxLayout()
                race_layout.setContentsMargins(5, 5, 5, 5)
                race_layout.setSpacing(6)
                
                race_label = QLabel("Irk:")
                race_combo = QComboBox()
                race_combo.setMaximumHeight(32)
                races = sorted(self.data.get("races", {}).keys())
                race_combo.addItems(races if races else ["Irk bulunamadı"])
                if self.current_character and self.current_character.get('race'):
                    idx = race_combo.findText(self.current_character.get('race', ''))
                    if idx >= 0:
                        race_combo.setCurrentIndex(idx)
                
                def update_race(text):
                    if self.current_character:
                        self.current_character['race'] = text
                        # Geliştirilmiş ırk özelliklerini uygula (ability scores + diğer özellikler)
                        self._update_ability_scores_from_race(text)
                        # Adım widget'ını yenile (ırk bilgilerini göstermek için)
                        self._populate_step_widgets()
                
                race_combo.currentTextChanged.connect(update_race)
                race_layout.addWidget(race_label)
                race_layout.addWidget(race_combo)
                
                # Irk bilgilerini göster
                if self.current_character and self.current_character.get('race'):
                    race_info = self.data.get("races", {}).get(self.current_character.get('race', ''), {})
                    if race_info:
                        info_label = QLabel()
                        info_text = f"<b>Yetiler:</b> {race_info.get('ability_score_increase', {})}<br>"
                        info_text += f"<b>Hız:</b> {race_info.get('speed', 30)}<br>"
                        info_text += f"<b>Boyut:</b> {race_info.get('size', 'Medium')}"
                        info_label.setText(info_text)
                        info_label.setWordWrap(True)
                        race_layout.addWidget(info_label)
                
                race_group.setLayout(race_layout)
                race_group.setMaximumHeight(250)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                if layout.count() >= 2:
                    layout.insertWidget(2, race_group)
                else:
                    layout.addWidget(race_group)
            
            # Adım 2: Yetenek Puanları
            elif step['name'] == "Yetenek Puanları":
                if hasattr(self, 'ability_spins'):
                    pb_group = QGroupBox("Yetenek Puanları (Point-Buy)")
                    pb_layout = QVBoxLayout()
                    pb_grid = QGridLayout()
                    pb_grid.setHorizontalSpacing(12)
                    pb_grid.setVerticalSpacing(10)
                    
                    for idx, ability in enumerate(self.abilities):
                        label = QLabel(ability)
                        spin = self.ability_spins[ability]
                        row = idx // 3
                        col = (idx % 3) * 2
                        pb_grid.addWidget(label, row, col)
                        pb_grid.addWidget(spin, row, col + 1)
                    
                    if hasattr(self, 'pb_info'):
                        pb_grid.addWidget(self.pb_info, (len(self.abilities) + 2) // 3, 0, 1, 6)
                    
                    pb_layout.addLayout(pb_grid)
                    pb_group.setLayout(pb_layout)
                    layout.insertWidget(2, pb_group)
            
            # Adım 3: Sınıf Becerileri
            elif step['name'] == "Sınıf Becerileri":
                skills_group = QGroupBox("Sınıf Becerileri")
                skills_layout = QVBoxLayout()
                skills_layout.setContentsMargins(5, 5, 5, 5)
                
                if self.current_character and self.current_character.get('class'):
                    class_name = self.current_character.get('class')
                    class_data = self.data.get("classes", {}).get(class_name, {})
                    class_skills = class_data.get("class_skills", [])
                    
                    if class_skills:
                        skills_label = QLabel("Sınıf Becerileri (Pathfinder 1e'de skill ranks ile geliştirilir):")
                        skills_label.setWordWrap(True)
                        skills_layout.addWidget(skills_label)
                        
                        skills_list = QListWidget()
                        skills_list.addItems(class_skills)
                        skills_list.setSelectionMode(QAbstractItemView.MultiSelection)
                        skills_layout.addWidget(skills_list)
                    else:
                        placeholder = QLabel("Bu sınıf için sınıf becerisi bilgisi bulunamadı.")
                        placeholder.setStyleSheet("color: #95a5a6; font-style: italic;")
                        skills_layout.addWidget(placeholder)
                else:
                    warning_label = QLabel("⚠️ Lütfen önce bir sınıf seçin.")
                    warning_label.setStyleSheet("color: #e74c3c; font-weight: bold; padding: 10px;")
                    skills_layout.addWidget(warning_label)
                
                skills_group.setLayout(skills_layout)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                if layout.count() >= 2:
                    layout.insertWidget(2, skills_group)
                else:
                    layout.addWidget(skills_group)
            
            # Adım 4: Feat'ler
            elif step['name'] == "Feat'ler":
                feats_group = QGroupBox("Feat Seçimi")
                feats_layout = QVBoxLayout()
                feats_layout.setContentsMargins(5, 5, 5, 5)
                
                feats_label = QLabel("Seçebileceğiniz Feat'ler:")
                feats_label.setWordWrap(True)
                feats_layout.addWidget(feats_label)
                
                feats_list = QListWidget()
                feats = sorted(self.data.get("feats", {}).keys())
                feats_list.addItems(feats if feats else ["Feat bulunamadı"])
                feats_list.setSelectionMode(QAbstractItemView.MultiSelection)
                
                # Seçili feat'leri yükle
                if self.current_character:
                    selected_feats = self.current_character.get('feats', [])
                    for feat in selected_feats:
                        items = feats_list.findItems(feat, Qt.MatchExactly)
                        for item in items:
                            item.setSelected(True)
                
                def update_feats():
                    selected = [item.text() for item in feats_list.selectedItems()]
                    if self.current_character:
                        self.current_character['feats'] = selected
                        self._auto_save_character()
                
                feats_list.itemSelectionChanged.connect(update_feats)
                feats_layout.addWidget(feats_list)
                
                feats_group.setLayout(feats_layout)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                if layout.count() >= 2:
                    layout.insertWidget(2, feats_group)
                else:
                    layout.addWidget(feats_group)
            
            # Adım 5: Büyüler (henüz çekilemedi)
            elif step['name'] == "Büyüler":
                spells_group = QGroupBox("Büyü Seçimi")
                spells_layout = QVBoxLayout()
                spells_layout.setContentsMargins(5, 5, 5, 5)
                
                warning_label = QLabel("⚠️ Büyüler henüz çekilemedi.\n"
                                      "Büyü verileri çekildikten sonra bu bölüm güncellenecek.")
                warning_label.setStyleSheet("color: #e74c3c; font-weight: bold; padding: 20px;")
                warning_label.setWordWrap(True)
                spells_layout.addWidget(warning_label)
                
                spells_group.setLayout(spells_layout)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                if layout.count() >= 2:
                    layout.insertWidget(2, spells_group)
                else:
                    layout.addWidget(spells_group)
            
            # Adım 6: Ekipman
            elif step['name'] == "Ekipman":
                equipment_group = QGroupBox("Başlangıç Ekipmanı")
                equipment_layout = QVBoxLayout()
                equipment_layout.setContentsMargins(5, 5, 5, 5)
                
                info_label = QLabel("Pathfinder 1e ekipman seçimi yakında eklenecek.\n"
                                   "Şimdilik envanter sekmesini kullanabilirsiniz.")
                info_label.setWordWrap(True)
                info_label.setStyleSheet("color: #7f8c8d; padding: 10px;")
                equipment_layout.addWidget(info_label)
                
                equipment_group.setLayout(equipment_layout)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                if layout.count() >= 2:
                    layout.insertWidget(2, equipment_group)
                else:
                    layout.addWidget(equipment_group)
            
            # Adım 7: Kişilik
            elif step['name'] == "Kişilik":
                personality_group = QGroupBox("Kişilik ve Fiziksel Özellikler")
                personality_layout = QVBoxLayout()
                personality_layout.setContentsMargins(5, 5, 5, 5)
                
                # Basit text edit'ler - ileride genişletilebilir
                if not hasattr(self, 'personality_edit'):
                    self.personality_edit = QTextEdit()
                    self.personality_edit.setPlaceholderText("Karakter kişilik özellikleri...")
                
                if not hasattr(self, 'physical_edit'):
                    self.physical_edit = QTextEdit()
                    self.physical_edit.setPlaceholderText("Fiziksel özellikler...")
                
                personality_layout.addWidget(QLabel("Kişilik:"))
                personality_layout.addWidget(self.personality_edit)
                personality_layout.addWidget(QLabel("Fiziksel Özellikler:"))
                personality_layout.addWidget(self.physical_edit)
                
                personality_group.setLayout(personality_layout)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                if layout.count() >= 2:
                    layout.insertWidget(2, personality_group)
                else:
                    layout.addWidget(personality_group)
            
            # Adım 8: Özet
            elif step['name'] == "Özet":
                summary_group = QGroupBox("Karakter Özeti")
                summary_layout = QVBoxLayout()
                summary_layout.setContentsMargins(5, 5, 5, 5)
                
                summary_text = QTextEdit()
                summary_text.setReadOnly(True)
                summary_text.setStyleSheet("""
                    QTextEdit {
                        background-color: #f8f9fa;
                        border: 1px solid #dee2e6;
                        border-radius: 5px;
                        padding: 10px;
                        font-size: 12px;
                    }
                """)
                
                # Özet widget'ını sakla (güncellemek için)
                if not hasattr(self, 'summary_text_widget'):
                    self.summary_text_widget = summary_text
                
                if self.current_character:
                    char = self.current_character
                    summary_html = f"""
                    <h2>{char.get('name', 'İsimsiz')}</h2>
                    <p><b>Sınıf:</b> {char.get('class', 'Seçilmedi')}</p>
                    <p><b>Irk:</b> {char.get('race', 'Seçilmedi')}</p>
                    <p><b>Seviye:</b> {char.get('level', 1)}</p>
                    """
                    
                    # Yetenek puanları
                    if hasattr(self, 'ability_spins'):
                        summary_html += "<h3>Yetenek Puanları:</h3><ul>"
                        for ability in self.abilities:
                            value = self.ability_spins[ability].value()
                            modifier = (value - 10) // 2
                            mod_str = f"+{modifier}" if modifier >= 0 else str(modifier)
                            summary_html += f"<li><b>{ability}:</b> {value} ({mod_str})</li>"
                        summary_html += "</ul>"
                    
                    # Feat'ler
                    if char.get('feats'):
                        summary_html += f"<h3>Feat'ler:</h3><ul>"
                        for feat in char.get('feats', []):
                            summary_html += f"<li>{feat}</li>"
                        summary_html += "</ul>"
                    
                    summary_text.setHtml(summary_html)
                else:
                    summary_text.setPlainText("Henüz bir karakter oluşturulmadı.")
                
                summary_layout.addWidget(summary_text)
                summary_group.setLayout(summary_layout)
                # Layout'ta başlık (0) ve açıklama (1) var, widget'ı 2. pozisyona ekle
                if layout.count() >= 2:
                    layout.insertWidget(2, summary_group)
                else:
                    layout.addWidget(summary_group)
    
    def _build_basic_widgets(self):
        """Temel widget'ları oluştur (ability spins, vs.)"""
        # Pathfinder 1e yetenekleri (D&D ile aynı)
        self.abilities = ["Strength", "Dexterity", "Constitution", "Intelligence", "Wisdom", "Charisma"]
        self.ability_spins = {}
        
        for ability in self.abilities:
            spin = QSpinBox()
            spin.setRange(7, 18)  # Pathfinder 1e point-buy range
            spin.setValue(10)
            spin.valueChanged.connect(self._update_point_buy_info)
            spin.valueChanged.connect(self._auto_save_character)
            self.ability_spins[ability] = spin
        
        # Point-buy bilgisi
        self.pb_info = QLabel("Kalan puan: 25 (Pathfinder 1e point-buy)")
        self.pb_info.setStyleSheet("font-weight: bold; color: #27ae60; margin-top: 10px;")
        self._update_point_buy_info()
    
    def _clear_layout(self, layout):
        """Layout'taki widget'ları temizle"""
        if not layout:
            return
        while layout.count():
            item = layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
            elif item.layout():
                self._clear_layout(item.layout())
                item.layout().deleteLater()
    
    def _update_point_buy_info(self):
        """Point-buy bilgisini güncelle"""
        if not hasattr(self, 'ability_spins') or not hasattr(self, 'pb_info'):
            return
        
        # Pathfinder 1e point-buy sistemi (basitleştirilmiş)
        total_cost = 0
        point_buy_costs = {7: -4, 8: -2, 9: -1, 10: 0, 11: 1, 12: 2, 13: 3, 14: 5, 15: 7, 16: 10, 17: 13, 18: 17}
        
        for ability in self.abilities:
            value = self.ability_spins[ability].value()
            total_cost += point_buy_costs.get(value, 0)
        
        remaining = 25 - total_cost
        color = "#27ae60" if remaining >= 0 else "#e74c3c"
        self.pb_info.setText(f"Kalan puan: {remaining} / 25 (Pathfinder 1e point-buy)")
        self.pb_info.setStyleSheet(f"font-weight: bold; color: {color}; margin-top: 10px;")
    
    def _update_ability_scores_from_race(self, race_name: str):
        """Irk seçildiğinde yetenek puanlarını ve tüm ırk özelliklerini güncelle - GELİŞTİRİLMİŞ"""
        if not race_name:
            return
        
        race_data = self.data.get("races", {}).get(race_name, {})
        if not race_data:
            return
        
        # 1. ABILITY SCORE INCREASES - Önceki bonusları kaldır
        if hasattr(self, 'ability_spins') and hasattr(self, '_current_race_bonus'):
            for ability, bonus in self._current_race_bonus.items():
                if ability in self.ability_spins:
                    current = self.ability_spins[ability].value()
                    self.ability_spins[ability].setValue(max(7, current - bonus))  # Minimum 7
        
        # Yeni ırk bonuslarını uygula
        ability_bonuses = race_data.get("ability_score_increase", {})
        self._current_race_bonus = {}
        
        # "any" bonus varsa (Human gibi), kullanıcıya seçim yaptır
        if "any" in ability_bonuses:
            bonus_value = ability_bonuses["any"]
            from PySide6.QtWidgets import QInputDialog
            abilities = ["Strength", "Dexterity", "Constitution", "Intelligence", "Wisdom", "Charisma"]
            ability, ok = QInputDialog.getItem(
                self, 
                "Yetenek Puanı Seçimi",
                f"Bu ırk {bonus_value} puan ekleyebilir. Hangi yeteneğe eklemek istersiniz?",
                abilities,
                0,
                False
            )
            if ok and ability:
                if ability in self.ability_spins:
                    current = self.ability_spins[ability].value()
                    self.ability_spins[ability].setValue(min(18, current + bonus_value))  # Maximum 18
                    self._current_race_bonus[ability] = bonus_value
        else:
            # Belirli yeteneklere bonus ekle
            for ability, bonus in ability_bonuses.items():
                ability_normalized = ability.capitalize()
                if ability_normalized in self.ability_spins:
                    current = self.ability_spins[ability_normalized].value()
                    self.ability_spins[ability_normalized].setValue(min(18, current + bonus))
                    self._current_race_bonus[ability_normalized] = bonus
        
        # 2. IRK BİLGİLERİNİ KARAKTERE EKLE
        if self.current_character:
            # Temel bilgiler
            self.current_character['race'] = race_name
            self.current_character['race_data'] = {
                'size': race_data.get('size', 'Medium'),
                'speed': race_data.get('speed', 30),
                'speed_special': race_data.get('speed_special', ''),
                'vision': race_data.get('vision', 'normal'),
                'vision_range': race_data.get('vision_range', 0),
            }
            
            # Languages - otomatik dilleri karaktere ekle
            if not self.current_character.get('languages'):
                self.current_character['languages'] = []
            
            auto_languages = race_data.get('languages_automatic', [])
            # Temizle (eski ırkın dillerini kaldırmak için)
            if auto_languages:
                # Yeni dilleri ekle (duplicate kontrolü ile)
                for lang in auto_languages:
                    if lang not in self.current_character['languages'] and len(lang) < 50:
                        self.current_character['languages'].append(lang)
            
            # Bonus diller listesini sakla (kullanıcı seçebilir)
            bonus_languages = race_data.get('languages_bonus', [])
            self.current_character['race_data']['bonus_languages'] = bonus_languages
            
            # Traits - ırk özelliklerini karaktere ekle
            traits = race_data.get('traits', [])
            traits_detailed = race_data.get('traits_detailed', {})
            if traits or traits_detailed:
                self.current_character['race_data']['traits'] = traits
                self.current_character['race_data']['traits_detailed'] = traits_detailed
            
            # Favored class bilgilerini ekle
            favored_classes = race_data.get('favored_classes', [])
            favored_class_bonus = race_data.get('favored_class_bonus', '')
            if favored_classes or favored_class_bonus:
                self.current_character['race_data']['favored_classes'] = favored_classes
                self.current_character['race_data']['favored_class_bonus'] = favored_class_bonus
            
            # Vision bilgisini ekle
            vision = race_data.get('vision', 'normal')
            vision_range = race_data.get('vision_range', 0)
            if vision != 'normal' or vision_range > 0:
                self.current_character['race_data']['vision'] = vision
                self.current_character['race_data']['vision_range'] = vision_range
            
            # Spell resistance
            spell_resistance = race_data.get('spell_resistance')
            if spell_resistance:
                self.current_character['race_data']['spell_resistance'] = spell_resistance
            
            # Irk açıklaması
            description = race_data.get('description', '')
            if description:
                self.current_character['race_data']['description'] = description
        
        # 3. INFO PANEL'İ GÜNCELLE (ırk bilgilerini göster)
        if hasattr(self, 'info_text') and race_data:
            info_html = f"<h3>{race_name}</h3>"
            
            # Ability score increase text
            ability_text = race_data.get('ability_score_increase_text', '')
            if ability_text:
                info_html += f"<p><b>Yetenek Puanı:</b> {ability_text}</p>"
            
            # Size ve Speed
            size = race_data.get('size', 'Medium')
            speed = race_data.get('speed', 30)
            speed_special = race_data.get('speed_special', '')
            info_html += f"<p><b>Boyut:</b> {size}</p>"
            info_html += f"<p><b>Hız:</b> {speed} feet"
            if speed_special and speed_special != str(speed):
                info_html += f" ({speed_special[:100]})"
            info_html += "</p>"
            
            # Vision
            vision = race_data.get('vision', 'normal')
            vision_range = race_data.get('vision_range', 0)
            if vision != 'normal':
                vision_text = vision.capitalize()
                if vision_range > 0:
                    vision_text += f" ({vision_range} feet)"
                info_html += f"<p><b>Görüş:</b> {vision_text}</p>"
            
            # Languages
            auto_langs = race_data.get('languages_automatic', [])
            bonus_langs = race_data.get('languages_bonus', [])
            if auto_langs:
                info_html += f"<p><b>Diller (Otomatik):</b> {', '.join(auto_langs[:5])}</p>"
            if bonus_langs:
                info_html += f"<p><b>Bonus Diller:</b> {', '.join(bonus_langs[:5])}</p>"
            
            # Traits (ilk 3)
            traits = race_data.get('traits', [])
            if traits:
                info_html += f"<p><b>Irk Özellikleri:</b></p><ul>"
                for trait in traits[:5]:
                    info_html += f"<li>{trait}</li>"
                info_html += "</ul>"
            
            # Favored class
            favored_classes = race_data.get('favored_classes', [])
            if favored_classes:
                info_html += f"<p><b>Favored Class:</b> {', '.join(favored_classes[:3])}</p>"
            
            # Description
            description = race_data.get('description', '')
            if description:
                info_html += f"<p><i>{description[:300]}...</i></p>"
            
            self.info_text.setHtml(info_html)
        
        # 4. OTOMATIK KAYDET
        self._auto_save_character()
    
    def _auto_save_character(self):
        """Karakteri otomatik olarak kaydet"""
        if not self.current_character:
            return
        
        # Mevcut karakter verisini güncelle
        character = self._collect_character_data()
        if character:
            self.current_character.update(character)
        
        # Dosyaya kaydet (eğer dosya yolu varsa)
        if hasattr(self, 'current_character_file') and self.current_character_file:
            try:
                self._save_character_to_file()
            except Exception:
                pass  # Sessizce başarısız ol, kullanıcıya rahatsızlık verme
    
    def _save_character_to_file(self, change_note: str = ""):
        """Mevcut karakteri dosyaya kaydet"""
        if not hasattr(self, 'current_character') or not self.current_character:
            return
        
        if not hasattr(self, 'current_character_file') or not self.current_character_file:
            return
        
        try:
            path = Path(self.current_character_file)
            path.parent.mkdir(parents=True, exist_ok=True)
            
            # Karakter verisini topla
            character = self._collect_character_data()
            
            # Karakteri kaydet
            with path.open("w", encoding="utf-8") as f:
                json.dump(character, f, ensure_ascii=False, indent=2)
        except Exception as e:
            # Sessizce başarısız ol, kullanıcıya rahatsızlık verme
            pass
    
    def _update_summary_step(self):
        """Özet adımındaki içeriği güncelle"""
        if not hasattr(self, 'current_character') or not self.current_character:
            return
        
        # Özet adımının widget'ını bul
        summary_index = None
        for i, step in enumerate(self.steps):
            if step['name'] == "Özet":
                summary_index = i
                break
        
        if summary_index is None or summary_index >= len(self.step_widgets):
            return
        
        layout = self.step_widgets[summary_index].layout()
        if not layout:
            return
        
        # Summary widget'ını bul ve güncelle
        for i in range(layout.count()):
            item = layout.itemAt(i)
            if item and item.widget():
                widget = item.widget()
                if isinstance(widget, QGroupBox) and widget.title() == "Karakter Özeti":
                    inner_layout = widget.layout()
                    if inner_layout and inner_layout.count() > 0:
                        text_item = inner_layout.itemAt(0)
                        if text_item and text_item.widget() and isinstance(text_item.widget(), QTextEdit):
                            summary_text = text_item.widget()
                            char = self.current_character
                            summary_html = f"""
                            <h2>{char.get('name', 'İsimsiz')}</h2>
                            <p><b>Sınıf:</b> {char.get('class', 'Seçilmedi')}</p>
                            <p><b>Irk:</b> {char.get('race', 'Seçilmedi')}</p>
                            <p><b>Seviye:</b> {char.get('level', 1)}</p>
                            """
                            
                            # Yetenek puanları
                            if hasattr(self, 'ability_spins'):
                                summary_html += "<h3>Yetenek Puanları:</h3><ul>"
                                for ability in self.abilities:
                                    value = self.ability_spins[ability].value()
                                    modifier = (value - 10) // 2
                                    mod_str = f"+{modifier}" if modifier >= 0 else str(modifier)
                                    summary_html += f"<li><b>{ability}:</b> {value} ({mod_str})</li>"
                                summary_html += "</ul>"
                            
                            # Feat'ler
                            if char.get('feats'):
                                summary_html += f"<h3>Feat'ler:</h3><ul>"
                                for feat in char.get('feats', []):
                                    summary_html += f"<li>{feat}</li>"
                                summary_html += "</ul>"
                            
                            summary_text.setHtml(summary_html)
                            break
    
    def _complete_character(self):
        """Karakter oluşturmayı tamamla"""
        if not self.current_character:
            QMessageBox.warning(self, "Uyarı", "Lütfen önce bir karakter oluşturun.")
            return
        QMessageBox.information(self, "Başarılı", "Karakter oluşturma tamamlandı!\n\nNot: Pathfinder 1e karakter oluşturma özellikleri henüz tam geliştirilmedi.")
    
    def _build_toolbar(self) -> QWidget:
        """Pathfinder 1e toolbar'ı"""
        widget = QWidget()
        bar = QHBoxLayout(widget)
        bar.setContentsMargins(0, 0, 0, 0)
        
        new_btn = QPushButton("Yeni Karakter")
        new_btn.clicked.connect(self._start_new_character)
        
        load_btn = QPushButton("Karakter Yükle")
        load_btn.clicked.connect(self._load_character)
        
        save_btn = QPushButton("Kaydet")
        save_btn.clicked.connect(self._save_character)
        
        pdf_btn = QPushButton("PDF Export")
        pdf_btn.clicked.connect(self._export_pdf)
        
        bar.addWidget(new_btn)
        bar.addWidget(load_btn)
        bar.addWidget(save_btn)
        bar.addWidget(pdf_btn)
        bar.addStretch()
        
        return widget
    
    def _start_new_character(self):
        """Yeni karakter yaratmaya başla - DndPage'e benzer"""
        classes = sorted(self.data.get("classes", {}).keys())
        if not classes:
            QMessageBox.warning(self, "Uyarı", "Herhangi bir sınıf verisi bulunamadı.")
            return
        
        # CharacterIntroDialog kullan (DndPage ile aynı)
        dialog = CharacterIntroDialog(self, classes)
        if dialog.exec() != QDialog.Accepted:
            return
        
        character_name, class_name = dialog.get_values()
        if not character_name:
            return
        
        # Karakter verisi oluştur
        self.current_character = {
            "system": self.SYSTEM_NAME,
            "name": character_name,
            "race": "",
            "class": class_name,
            "level": 1,
            "abilities": {},
            "skills": {},
            "equipment": [],
            "spells": {},
            "feats": [],
            "languages": [],
            "personality": {},
            "physical": {},
            "appearance": {}
        }
        
        # Varsayılan dosya adı
        self.current_character_file = str(_ensure_characters_dir() / f"{character_name}_pf1e.json")
        
        # Karakter formunu güncelle
        self._load_character_to_gui(self.current_character)
        
        # Adım widget'larını güncelle
        if hasattr(self, '_populate_step_widgets'):
            self._populate_step_widgets()
        
        # İlk adıma git
        self._go_to_step(0)
        
        # İlk kaydı yap
        self._save_character_to_file()
    
    def _load_character(self):
        """Karakter yükle - DndPage'e benzer"""
        data, path = _load_character_via_dialog(self, "Pathfinder 1e Karakteri Yükle", self.SYSTEM_NAME)
        if not data:
            return
        
        # Karakter verisini yükle
        self.current_character = data
        self.current_character_file = path
        
        # GUI'ye yükle
        self._load_character_to_gui(data)
        
        # Adım widget'larını güncelle
        if hasattr(self, '_populate_step_widgets'):
            self._populate_step_widgets()
        
        # İlk adıma git
        self._go_to_step(0)
        
        # Son açılanlara ekle
        if path:
            add_recent_character(APP_BASE_DIR, path, data.get("name", ""))
        
        QMessageBox.information(self, "Başarılı", "Pathfinder 1e karakteri yüklendi.")
    
    def _load_character_to_gui(self, character: dict):
        """Karakteri GUI'ye yükle"""
        if not character:
            return
        
        # Temel bilgileri güncelle
        if hasattr(self, 'ability_spins') and character.get('abilities'):
            for ability, value in character.get('abilities', {}).items():
                if ability in self.ability_spins:
                    self.ability_spins[ability].setValue(value)
        
        # Feat'leri güncelle (populate_step_widgets'te zaten yüklenecek)
    
    def _save_character(self):
        """Karakter kaydet - DndPage'e benzer"""
        if not self.current_character:
            QMessageBox.warning(self, "Uyarı", "Önce bir karakter oluşturun.")
            return
        
        # Karakter verisini topla
        character = self._collect_character_data()
        if not character:
            return
        
        # Varsayılan dosya adı
        character_name = character.get('name', 'pathfinder_karakter')
        default_name = f"{character_name}_pf1e"
        
        # Kaydetme dialog'u aç
        _save_character_via_dialog(self, character, "Pathfinder 1e Karakterini Kaydet", default_name)
        
        # Dosya yolu varsa current_character_file'ı güncelle
        # (Dialog'da seçilen dosya yolu _save_character_via_dialog içinde kaydediliyor)
    
    def _collect_character_data(self) -> dict:
        """GUI'den karakter verisini topla"""
        if not self.current_character:
            return {}
        
        character = dict(self.current_character)
        
        # Yetenek puanlarını ekle
        if hasattr(self, 'ability_spins'):
            character['abilities'] = {}
            for ability in self.abilities:
                character['abilities'][ability] = self.ability_spins[ability].value()
        
        # Feat'ler zaten current_character'da (update_feats fonksiyonunda)
        
        # Kişilik özellikleri
        if hasattr(self, 'personality_edit'):
            character['personality']['description'] = self.personality_edit.toPlainText()
        
        if hasattr(self, 'physical_edit'):
            character['physical']['description'] = self.physical_edit.toPlainText()
        
        return character
    
    def _export_pdf(self):
        """PDF export"""
        if not self.current_character:
            QMessageBox.warning(self, "Uyarı", "Önce bir karakter oluşturun.")
            return
        
        QMessageBox.information(self, "Bilgi", "Pathfinder 1e PDF export özelliği henüz geliştirilmedi.")


class MainWindow(QtWidgets.QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("Diyargezer - FRP Karakter Oluşturucu")
        self.setMinimumSize(1000, 700)
        self.resize(1200, 800)
        
        # Dark theme uygula
        self._apply_dark_theme()
        
        # Keyboard shortcuts ekle
        self._setup_shortcuts()
        
        # Pencere ikonu ayarla
        self._set_window_icon()

        # Ana widget oluştur (logo header + tab widget)
        main_widget = QWidget()
        main_layout = QVBoxLayout(main_widget)
        main_layout.setContentsMargins(5, 5, 5, 5)
        main_layout.setSpacing(5)
        
        # Logo header ekle
        header_widget = self._create_header()
        header_widget.setMaximumHeight(140)  # Header maksimum yükseklik
        main_layout.addWidget(header_widget)
        
        # Tab widget
        central = QtWidgets.QTabWidget()
        central.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        central.addTab(DndPage(), "🎲 D&D 5e")
        central.addTab(MmPage(), "🦸 M&M")
        central.addTab(VtmPage(), "🧛 VtM")
        central.addTab(PathfinderPage(), "⚔️ Pathfinder 1e")
        main_layout.addWidget(central)
        
        self.setCentralWidget(main_widget)

    def _apply_dark_theme(self):
        """Dark theme uygula"""
        self.setStyleSheet("""
            QMainWindow {
                background-color: #2c3e50;
                color: #ecf0f1;
            }
            QTabWidget::pane {
                border: 2px solid #34495e;
                border-radius: 8px;
                background-color: #2c3e50;
                margin-top: -2px;
            }
            QTabBar::tab {
                background: qlineargradient(x1: 0, y1: 0, x2: 0, y2: 1,
                    stop: 0 #34495e, stop: 1 #2c3e50);
                color: #ecf0f1;
                padding: 12px 24px;
                margin-right: 3px;
                border-top-left-radius: 8px;
                border-top-right-radius: 8px;
                font-weight: bold;
                font-size: 14px;
                min-width: 120px;
                border: 1px solid #34495e;
            }
            QTabBar::tab:selected {
                background: qlineargradient(x1: 0, y1: 0, x2: 0, y2: 1,
                    stop: 0 #3498db, stop: 1 #2980b9);
                border-bottom: 2px solid #3498db;
            }
            QTabBar::tab:hover {
                background: qlineargradient(x1: 0, y1: 0, x2: 0, y2: 1,
                    stop: 0 #5dade2, stop: 1 #3498db);
            }
            QTabBar::tab:!selected {
                margin-top: 3px;
            }
            QGroupBox {
                font-weight: bold;
                border: 2px solid #34495e;
                border-radius: 8px;
                margin-top: 10px;
                padding-top: 10px;
                background-color: #34495e;
                color: #ecf0f1;
            }
            QGroupBox::title {
                subcontrol-origin: margin;
                left: 10px;
                padding: 0 10px 0 10px;
                background-color: #2c3e50;
            }
        """)

    def _setup_shortcuts(self):
        """Keyboard shortcuts ayarla"""
        # Ctrl+N: Yeni karakter
        new_char_shortcut = QShortcut(QKeySequence("Ctrl+N"), self)
        new_char_shortcut.activated.connect(self._new_character_shortcut)
        
        # Ctrl+O: Karakter yükle
        load_char_shortcut = QShortcut(QKeySequence("Ctrl+O"), self)
        load_char_shortcut.activated.connect(self._load_character_shortcut)
        
        # Ctrl+S: Karakter kaydet
        save_char_shortcut = QShortcut(QKeySequence("Ctrl+S"), self)
        save_char_shortcut.activated.connect(self._save_character_shortcut)
        
        # Ctrl+E: PDF export
        export_shortcut = QShortcut(QKeySequence("Ctrl+E"), self)
        export_shortcut.activated.connect(self._export_shortcut)
        
        # F1: Yardım
        help_shortcut = QShortcut(QKeySequence("F1"), self)
        help_shortcut.activated.connect(self._show_help)

    def _new_character_shortcut(self):
        """Yeni karakter oluştur (Ctrl+N)"""
        # D&D sayfasına geç ve yeni karakter başlat
        if hasattr(self, 'centralWidget'):
            tab_widget = self.centralWidget()
            if isinstance(tab_widget, QTabWidget):
                tab_widget.setCurrentIndex(0)  # D&D sekmesi

    def _load_character_shortcut(self):
        """Karakter yükle (Ctrl+O)"""
        # D&D sayfasına geç ve karakter yükleme dialog'unu aç
        if hasattr(self, 'centralWidget'):
            tab_widget = self.centralWidget()
            if isinstance(tab_widget, QTabWidget):
                tab_widget.setCurrentIndex(0)  # D&D sekmesi

    def _save_character_shortcut(self):
        """Karakter kaydet (Ctrl+S)"""
        # Otomatik kaydetme zaten aktif, bilgi mesajı göster
        QMessageBox.information(self, "Bilgi", "Karakter otomatik olarak kaydediliyor!")

    def _export_shortcut(self):
        """PDF export (Ctrl+E)"""
        # D&D sayfasına geç ve export yap
        if hasattr(self, 'centralWidget'):
            tab_widget = self.centralWidget()
            if isinstance(tab_widget, QTabWidget):
                tab_widget.setCurrentIndex(0)  # D&D sekmesi

    def _show_help(self):
        """Yardım göster (F1)"""
        help_text = """
🎮 Diyargezer - FRP Karakter Oluşturucu

⌨️ Klavye Kısayolları:
• Ctrl+N: Yeni Karakter Oluştur
• Ctrl+O: Karakter Yükle
• Ctrl+S: Karakter Kaydet
• Ctrl+E: PDF Export
• F1: Bu Yardım

🎯 Özellikler:
• D&D 5e karakter oluşturma
• Otomatik istatistik hesaplama
• Envanter yönetimi
• Büyü sistemi
• Dice roller
• PDF export

📧 Destek: [Destek bilgileri]
        """
        QMessageBox.information(self, "Yardım - Klavye Kısayolları", help_text)

    def _create_header(self) -> QWidget:
        """Ana pencere için logo header oluştur"""
        header_widget = QWidget()
        header_widget.setStyleSheet("background-color: #34495e; border-bottom: 2px solid #2c3e50;")
        header_widget.setMaximumHeight(140)  # Header maksimum yükseklik
        header_layout = QHBoxLayout(header_widget)
        header_layout.setContentsMargins(15, 10, 15, 10)
        
        # Logo
        logo_path = Path(__file__).resolve().parents[1] / "assets/diyargezer_logo.png"
        if logo_path.exists():
            logo_label = QLabel()
            logo_pixmap = QPixmap(str(logo_path))
            if not logo_pixmap.isNull():
                # Logoyu küçült (maksimum 100x100, aspect ratio korunarak)
                scaled_pixmap = logo_pixmap.scaled(100, 100, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                logo_label.setPixmap(scaled_pixmap)
                logo_label.setScaledContents(True)  # Küçültülmüş boyutta göster
            logo_label.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
            logo_label.setFixedSize(100, 100)  # Sabit boyut
            header_layout.addWidget(logo_label)
        
        # Başlık
        title_label = QLabel("Diyargezer - FRP Karakter Oluşturucu")
        title_label.setStyleSheet("font-size: 20px; font-weight: bold; color: white; margin-left: 20px;")
        title_label.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
        title_label.setWordWrap(True)  # Uzun metinler için kelime kaydırma
        header_layout.addWidget(title_label)
        
        header_layout.addStretch()
        
        return header_widget
    
    def _set_window_icon(self):
        """Pencere ikonunu ayarla"""
        logo_path = Path(__file__).resolve().parents[1] / "assets/diyargezer_logo.png"
        if logo_path.exists():
            icon = QIcon(str(logo_path))
            self.setWindowIcon(icon)


def run():
    import qdarkstyle
    app = QApplication([])
    try:
        app.setStyleSheet(qdarkstyle.load_stylesheet(qt_api='pyside6'))
    except Exception:
        pass
    w = MainWindow()
    w.show()
    app.exec()


if __name__ == "__main__":
    run()

